insert into public.academy_kb_families (slug, name, short_name, kind, publisher, about, sort_order) values
  ('irc', 'International Residential Code', 'IRC', 'model_code', 'International Code Council (ICC)', 'Model code for one- and two-family dwellings and townhouses up to three stories. A state or city must adopt an edition (usually with amendments) before it is enforceable.', 10),
  ('ibc', 'International Building Code', 'IBC', 'model_code', 'International Code Council (ICC)', 'Model code for commercial and most non-residential buildings. Enforceable only where adopted.', 20),
  ('iebc', 'International Existing Building Code', 'IEBC', 'model_code', 'International Code Council (ICC)', 'Model code for repair, alteration, change of occupancy and additions to existing buildings.', 30),
  ('ipc', 'International Plumbing Code', 'IPC', 'model_code', 'International Code Council (ICC)', 'Model plumbing code. Some states use the Uniform Plumbing Code or their own plumbing code instead.', 40),
  ('imc', 'International Mechanical Code', 'IMC', 'model_code', 'International Code Council (ICC)', 'Model code for HVAC, exhaust and other mechanical systems.', 50),
  ('ifgc', 'International Fuel Gas Code', 'IFGC', 'model_code', 'International Code Council (ICC)', 'Model code for fuel gas piping and appliances.', 60),
  ('ifc', 'International Fire Code', 'IFC', 'model_code', 'International Code Council (ICC)', 'Model fire prevention code.', 70),
  ('iecc', 'International Energy Conservation Code', 'IECC', 'model_code', 'International Code Council (ICC)', 'Model energy code (insulation, windows, air sealing, duct and system efficiency).', 80),
  ('nec', 'National Electrical Code (NFPA 70)', 'NEC', 'standard', 'National Fire Protection Association (NFPA)', 'Electrical installation standard. States adopt an edition, often with amendments and their own effective dates.', 90),
  ('mn_rules', 'Minnesota Rules (State Building Code)', 'Minn. R.', 'state_rule', 'Minnesota Office of the Revisor of Statutes', 'Minnesota''s administrative rules that adopt and amend the model codes that make up the Minnesota State Building Code.', 200),
  ('osha_construction', 'OSHA Construction Standards (29 CFR Part 1926)', '29 CFR 1926', 'federal_regulation', 'U.S. Department of Labor, OSHA', 'Federal workplace safety rules for construction work. States with an OSHA-approved State Plan enforce their own standards, which must be at least as effective.', 300),
  ('osha_recordkeeping', 'OSHA Recordkeeping and Reporting (29 CFR Part 1904)', '29 CFR 1904', 'federal_regulation', 'U.S. Department of Labor, OSHA', 'Injury and illness records and the deadlines for reporting serious incidents.', 310),
  ('osha_state_plans', 'OSHA-Approved State Plans (29 CFR Part 1952)', '29 CFR 1952', 'federal_regulation', 'U.S. Department of Labor, OSHA', 'The federal list of states that run their own OSHA-approved workplace safety programs.', 320),
  ('epa_lead_rrp', 'EPA Lead Renovation, Repair and Painting Rule (40 CFR Part 745)', '40 CFR 745', 'federal_regulation', 'U.S. Environmental Protection Agency', 'Lead-safe work rules for paid renovation in pre-1978 housing and child-occupied facilities. Some states run EPA-authorized programs.', 330),
  ('fmcsa', 'FMCSA Motor Carrier Safety Regulations (49 CFR)', '49 CFR', 'federal_regulation', 'U.S. Department of Transportation, FMCSA', 'Federal commercial vehicle rules (drivers, inspections, drug and alcohol testing) for interstate commerce. States set intrastate rules.', 340)
on conflict (slug) do nothing;

