  (md5('academykb:adoption:mn-admin-1309')::uuid, 'MN', md5('academykb:source:mn-1309')::uuid, 'administers', null, 'The Minnesota State Building Code is the minimum standard statewide, but DLI states it is not enforceable by a municipality unless adopted by local ordinance. Confirm with the city, township or county building official for the project.', 'Minn. R. ch. 1309', 'https://www.revisor.mn.gov/rules/1309/', '2020-03-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:mn-admin-1346')::uuid, 'MN', md5('academykb:source:mn-1346')::uuid, 'administers', null, 'The Minnesota State Building Code is the minimum standard statewide, but DLI states it is not enforceable by a municipality unless adopted by local ordinance. Confirm with the city, township or county building official for the project.', 'Minn. R. ch. 1346', 'https://www.revisor.mn.gov/rules/1346/', '2020-04-06'::date, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:mn-admin-1322')::uuid, 'MN', md5('academykb:source:mn-1322')::uuid, 'administers', null, 'The Minnesota State Building Code is the minimum standard statewide, but DLI states it is not enforceable by a municipality unless adopted by local ordinance. Confirm with the city, township or county building official for the project.', 'Minn. R. ch. 1322', 'https://www.revisor.mn.gov/rules/1322/', null, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:mn-admin-1315')::uuid, 'MN', md5('academykb:source:mn-1315')::uuid, 'administers', null, 'Applies statewide to new electrical wiring, apparatus and equipment. Permits filed before Aug. 17, 2026 follow the 2023 NEC.', 'Minn. R. 1315.0200', 'https://www.revisor.mn.gov/rules/1315.0200/', '2026-08-17'::date, null, false, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:mn-irc-2018')::uuid, 'MN', md5('academykb:source:irc-2018')::uuid, 'adopts', null, 'IRC chapters 2 to 10 and 44, section P2904, Appendix K and Appendix Q apply where the municipality adopted the State Building Code. Chapter 1 is replaced by Minn. R. 1300; chapter 11 (energy) by Minn. R. 1322 and 1323; mechanical chapters by 1346; plumbing chapters by 4714 (except P2904); electrical chapters by 1315 (R314 and R315 stay). The Minnesota State Building Code is the minimum standard statewide, but DLI states it is not enforceable by a municipality unless adopted by local ordinance. Confirm with the city, township or county building official for the project.', 'Minn. R. 1309.0010', 'https://www.revisor.mn.gov/rules/1309.0010/', '2020-03-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:mn-ibc-2018')::uuid, 'MN', md5('academykb:source:ibc-2018')::uuid, 'adopts', null, 'The Minnesota State Building Code is the minimum standard statewide, but DLI states it is not enforceable by a municipality unless adopted by local ordinance. Confirm with the city, township or county building official for the project.', 'Minn. R. 1305.0011', 'https://www.revisor.mn.gov/rules/1305.0011/', '2020-03-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:mn-imc-2018')::uuid, 'MN', md5('academykb:source:imc-2018')::uuid, 'adopts', null, 'IMC chapters 2 to 15 as amended in Minn. R. ch. 1346. The Minnesota State Building Code is the minimum standard statewide, but DLI states it is not enforceable by a municipality unless adopted by local ordinance. Confirm with the city, township or county building official for the project.', 'Minn. R. 1346.0050', 'https://www.revisor.mn.gov/rules/1346.0050/', '2020-04-06'::date, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:mn-iecc-2012')::uuid, 'MN', md5('academykb:source:iecc-2012')::uuid, 'adopts', null, 'Residential provisions, chapters 2(RE) to 5(RE), as amended in Minn. R. ch. 1322. Effective date not yet verified. The Minnesota State Building Code is the minimum standard statewide, but DLI states it is not enforceable by a municipality unless adopted by local ordinance. Confirm with the city, township or county building official for the project.', 'Minn. R. 1322.0010', 'https://www.revisor.mn.gov/rules/1322.0010/', null, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:mn-nec-2026')::uuid, 'MN', md5('academykb:source:nec-2026')::uuid, 'adopts', null, 'Statewide. Electrical permits filed on or after Aug. 17, 2026 must comply with the 2026 NEC.', 'Minn. R. 1315.0200, subp. 1a', 'https://www.revisor.mn.gov/rules/1315.0200/', '2026-08-17'::date, null, false, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:mn-nec-2023')::uuid, 'MN', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Applied to electrical permits filed before Aug. 17, 2026.', 'Minn. R. 1315.0200 (prior version)', 'https://www.dli.mn.gov/business/electrical-contractors', null, '2026-08-17'::date, false, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
