  (md5('academykb:adoption:stateplan:AZ:osha_recordkeeping')::uuid, 'AZ', md5('academykb:source:osha-1952')::uuid, 'replaces', 'osha_recordkeeping', '1952.19 Arizona. OSHA-approved State Plan covering private-sector and state and local government employers. The state''s standards and enforcement govern and must be at least as effective as the federal rules.', '29 CFR 1952.19', 'https://www.ecfr.gov/current/title-29/section-1952.19', null, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:stateplan:NM:osha_construction')::uuid, 'NM', md5('academykb:source:osha-1952')::uuid, 'replaces', 'osha_construction', '1952.20 New Mexico. OSHA-approved State Plan covering private-sector and state and local government employers. The state''s standards and enforcement govern and must be at least as effective as the federal rules.', '29 CFR 1952.20', 'https://www.ecfr.gov/current/title-29/section-1952.20', null, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:stateplan:NM:osha_recordkeeping')::uuid, 'NM', md5('academykb:source:osha-1952')::uuid, 'replaces', 'osha_recordkeeping', '1952.20 New Mexico. OSHA-approved State Plan covering private-sector and state and local government employers. The state''s standards and enforcement govern and must be at least as effective as the federal rules.', '29 CFR 1952.20', 'https://www.ecfr.gov/current/title-29/section-1952.20', null, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
  (md5('academykb:adoption:stateplan:VA:osha_construction')::uuid, 'VA', md5('academykb:source:osha-1952')::uuid, 'replaces', 'osha_construction', '1952.21 Virginia. OSHA-approved State Plan covering private-sector and state and local government employers. The state''s standards and enforcement govern and must be at least as effective as the federal rules.', '29 CFR 1952.21', 'https://www.ecfr.gov/current/title-29/section-1952.21', null, null, true, '{}'::text[], 'verified', '2026-11-22T01:17:09Z'::timestamptz),
