insert into public.academy_kb_sections (id, source_id, section_number, citation, title, heading_path, kind, body_kind, body, summary, page, amends_source_id, amends_section, amend_action, trades, topics, effective_date, official_url, status, last_verified_at, content_hash, sort_order) values
  (md5('academykb:section:cfr:1926.20(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.20(a)', '29 CFR 1926.20(a)', 'General safety and health provisions: Contractor requirements', '29 CFR Part 1926 › § 1926.20 General safety and health provisions', 'requirement', 'full_text', '(a) Contractor requirements. (1) Section 107 of the Act requires that it shall be a condition of each contract which is entered into under legislation subject to Reorganization Plan Number 14 of 1950 (64 Stat. 1267), as defined in § 1926.12, and is for construction, alteration, and/or repair, including painting and decorating, that no contractor or subcontractor for any part of the contract work shall require any laborer or mechanic employed in the performance of the contract to work in surroundings or under working conditions which are unsanitary, hazardous, or dangerous to his health or safety.', null, null, null, null, null, '{}'::text[], array['safety program', 'inspections', 'competent person']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.20#p-1926.20(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '3f6beff6c1038da65d17677408de73dec379e3a06c31bea8c409c7198d39f4ef', 0),
  (md5('academykb:section:cfr:1926.20(b)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.20(b)', '29 CFR 1926.20(b)', 'General safety and health provisions: Accident prevention responsibilities', '29 CFR Part 1926 › § 1926.20 General safety and health provisions', 'requirement', 'full_text', '(b) Accident prevention responsibilities. (1) It shall be the responsibility of the employer to initiate and maintain such programs as may be necessary to comply with this part.
(2) Such programs shall provide for frequent and regular inspections of the job sites, materials, and equipment to be made by competent persons designated by the employers.
(3) The use of any machinery, tool, material, or equipment which is not in compliance with any applicable requirement of this part is prohibited. Such machine, tool, material, or equipment shall either be identified as unsafe by tagging or locking the controls to render them inoperable or shall be physically removed from its place of operation.
(4) The employer shall permit only those employees qualified by training or experience to operate equipment and machinery.', null, null, null, null, null, '{}'::text[], array['safety program', 'inspections', 'competent person']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.20#p-1926.20(b)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '0e60ec219bc9b9d97f5ddd475353200ff55667b288301a1056559f703f4960f2', 1),
  (md5('academykb:section:cfr:1926.20(c)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.20(c)', '29 CFR 1926.20(c)', 'General safety and health provisions: paragraph (c)', '29 CFR Part 1926 › § 1926.20 General safety and health provisions', 'requirement', 'full_text', '(c) The standards contained in this part shall apply with respect to employments performed in a workplace in a State, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, American Samoa, Guam, the Commonwealth of the Northern Mariana Islands, Wake Island, Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act, and Johnston Island.', null, null, null, null, null, '{}'::text[], array['safety program', 'inspections', 'competent person']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.20#p-1926.20(c)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '48183d6515028f43a6fdfa400f8a192ec3baa6537ae3b6ab63d0d4fa4d380a76', 2),
  (md5('academykb:section:cfr:1926.20(d)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.20(d)', '29 CFR 1926.20(d)', 'General safety and health provisions: paragraph (d)', '29 CFR Part 1926 › § 1926.20 General safety and health provisions', 'requirement', 'full_text', '(d) (1) If a particular standard is specifically applicable to a condition, practice, means, method, operation, or process, it shall prevail over any different general standard which might otherwise be applicable to the same condition, practice, means, method, operation, or process.
(2) On the other hand, any standard shall apply according to its terms to any employment and place of employment in any industry, even though particular standards are also prescribed for the industry to the extent that none of such particular standards applies.', null, null, null, null, null, '{}'::text[], array['safety program', 'inspections', 'competent person']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.20#p-1926.20(d)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'f5335297779b0153a070c8cc78be0aef8be6eab0ec90147b584eca1c4f8327a9', 3),
  (md5('academykb:section:cfr:1926.20(e)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.20(e)', '29 CFR 1926.20(e)', 'General safety and health provisions: paragraph (e)', '29 CFR Part 1926 › § 1926.20 General safety and health provisions', 'requirement', 'full_text', '(e) In the event a standard protects on its face a class of persons larger than employees, the standard shall be applicable under this part only to employees and their employment and places of employment.', null, null, null, null, null, '{}'::text[], array['safety program', 'inspections', 'competent person']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.20#p-1926.20(e)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '78ac7700835267535feb01302f1f6bd864d2a31580068a16112392db6c95fb68', 4),
  (md5('academykb:section:cfr:1926.20(f)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.20(f)', '29 CFR 1926.20(f)', 'General safety and health provisions: Compliance duties owed to each employee', '29 CFR Part 1926 › § 1926.20 General safety and health provisions', 'requirement', 'full_text', '(f) Compliance duties owed to each employee—(1) Personal protective equipment. Standards in this part requiring the employer to provide personal protective equipment (PPE), including respirators and other types of PPE, because of hazards to employees impose a separate compliance duty with respect to each employee covered by the requirement. The employer must provide PPE to each employee required to use the PPE, and each failure to provide PPE to an employee may be considered a separate violation.
(2) Training. Standards in this part requiring training on hazards and related matters, such as standards requiring that employees receive training or that the employer train employees, provide training to employees, or institute or implement a training program, impose a separate compliance duty with respect to each employee covered by the requirement. The employer must train each affected employee in the manner required by the standard, and each failure to train an employee may be considered a separate violation.', null, null, null, null, null, '{}'::text[], array['safety program', 'inspections', 'competent person']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.20#p-1926.20(f)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '20686decb627b037353fc55d5e9870532cee0d0845e85e2e4c47e15c23cedbdc', 5),
  (md5('academykb:section:cfr:1926.21')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.21', '29 CFR 1926.21', 'Safety training and education', '29 CFR Part 1926 › § 1926.21 Safety training and education', 'requirement', 'full_text', '(a) General requirements. The Secretary shall, pursuant to section 107(f) of the Act, establish and supervise programs for the education and training of employers and employees in the recognition, avoidance and prevention of unsafe conditions in employments covered by the act.
(b) Employer responsibility. (1) The employer should avail himself of the safety and health training programs the Secretary provides.
(2) The employer shall instruct each employee in the recognition and avoidance of unsafe conditions and the regulations applicable to his work environment to control or eliminate any hazards or other exposure to illness or injury.
(3) Employees required to handle or use poisons, caustics, and other harmful substances shall be instructed regarding the safe handling and use, and be made aware of the potential hazards, personal hygiene, and personal protective measures required.
(4) In job site areas where harmful plants or animals are present, employees who may be exposed shall be instructed regarding the potential hazards, and how to avoid injury, and the first aid procedures to be used in the event of injury.
(5) Employees required to handle or use flammable liquids, gases, or toxic materials shall be instructed in the safe handling and use of these materials and made aware of the specific requirements contained in subparts D, F, and other applicable subparts of this part.', 'Employers must instruct each employee to recognize and avoid unsafe conditions and the regulations that apply to their work.', null, null, null, null, '{}'::text[], array['training', 'safety training']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.21', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '67fab6dd06eb06e4e123a306a2623b0aa07557f0929715a472ceda0aec708f9c', 6),
  (md5('academykb:section:cfr:1926.95(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.95(a)', '29 CFR 1926.95(a)', 'Criteria for personal protective equipment: Application', '29 CFR Part 1926 › § 1926.95 Criteria for personal protective equipment', 'requirement', 'full_text', '(a) Application. Protective equipment, including personal protective equipment for eyes, face, head, and extremities, protective clothing, respiratory devices, and protective shields and barriers, shall be provided, used, and maintained in a sanitary and reliable condition wherever it is necessary by reason of hazards of processes or environment, chemical hazards, radiological hazards, or mechanical irritants encountered in a manner capable of causing injury or impairment in the function of any part of the body through absorption, inhalation or physical contact.', null, null, null, null, null, '{}'::text[], array['ppe', 'personal protective equipment']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.95#p-1926.95(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'fa2860b981f9a40914994e37db4806b9e598522c1291b4cc29d454b6fc8d3730', 7),
  (md5('academykb:section:cfr:1926.100')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.100', '29 CFR 1926.100', 'Head protection', '29 CFR Part 1926 › § 1926.100 Head protection', 'requirement', 'full_text', '(a) Employees working in areas where there is a possible danger of head injury from impact, or from falling or flying objects, or from electrical shock and burns, shall be protected by protective helmets.
(b) Criteria for head protection. (1) The employer must provide each employee with head protection that meets the specifications contained in any of the following consensus standards:
(i) American National Standards Institute (ANSI) Z89.1-2009, “American National Standard for Industrial Head Protection,” incorporated by reference in § 1926.6;
(ii) American National Standards Institute (ANSI) Z89.1-2003, “American National Standard for Industrial Head Protection,” incorporated by reference in § 1926.6; or
(iii) American National Standards Institute (ANSI) Z89.1-1997, “American National Standard for Personnel Protection—Protective Headwear for Industrial Workers—Requirements,” incorporated by reference in § 1926.6.
(2) The employer must ensure that the head protection provided for each employee exposed to high-voltage electric shock and burns also meets the specifications contained in Section 9.7 (“Electrical Insulation”) of any of the consensus standards identified in paragraph (b)(1) of this section.
(3) OSHA will deem any head protection device that the employer demonstrates is at least as effective as a head protection device constructed in accordance with one of the consensus standards identified in paragraph (b)(1) of this section to be in compliance with the requirements of this section.', 'Workers exposed to head injury from impact, falling or flying objects, or electrical shock must wear protective helmets.', null, null, null, null, '{}'::text[], array['hard hat', 'head protection', 'ppe']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.100', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '907d359c650fd75506b2ea72dec8834cfe98d023d4b7365d62de484280ac5df8', 8),
  (md5('academykb:section:cfr:1926.102(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.102(a)', '29 CFR 1926.102(a)', 'Eye and face protection: General', '29 CFR Part 1926 › § 1926.102 Eye and face protection', 'requirement', 'full_text', '(a) General. (1) The employer shall ensure that each affected employee uses appropriate eye or face protection when exposed to eye or face hazards from flying particles, molten metal, liquid chemicals, acids or caustic liquids, chemical gases or vapors, or potentially injurious light radiation.
(2) The employer shall ensure that each affected employee uses eye protection that provides side protection when there is a hazard from flying objects. Detachable side protectors (e.g. clip-on or slide-on side shields) meeting the pertinent requirements of this section are acceptable.
(3) The employer shall ensure that each affected employee who wears prescription lenses while engaged in operations that involve eye hazards wears eye protection that incorporates the prescription in its design, or wears eye protection that can be worn over the prescription lenses without disturbing the proper position of the prescription lenses or the protective lenses.
(4) Eye and face PPE shall be distinctly marked to facilitate identification of the manufacturer.
(5) Protectors shall meet the following minimum requirements:
(i) They shall provide adequate protection against the particular hazards for which they are designed.
(ii) They shall be reasonably comfortable when worn under the designated conditions.
(iii) They shall fit snugly and shall not unduly interfere with the movements of the wearer.
(iv) They shall be durable.
(v) They shall be capable of being disinfected.
(vi) They shall be easily cleanable.', null, null, null, null, null, '{}'::text[], array['eye protection', 'face protection', 'ppe']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.102#p-1926.102(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '95fadfa7d481abac32368df4586a0bb972ec2bc0672f51ea7891fe251fbfe50e', 9),
  (md5('academykb:section:cfr:1926.404(b)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.404(b)', '29 CFR 1926.404(b)', 'Wiring design and protection: Branch circuits', '29 CFR Part 1926 › § 1926.404 Wiring design and protection', 'requirement', 'full_text', '(b) Branch circuits—(1) Ground-fault protection—(i) General. The employer shall use either ground fault circuit interrupters as specified in paragraph (b)(1)(ii) of this section or an assured equipment grounding conductor program as specified in paragraph (b)(1)(iii) of this section to protect employees on construction sites. These requirements are in addition to any other requirements for equipment grounding conductors.
(ii) Ground-fault circuit interrupters. All 120-volt, single-phase, 15- and 20-ampere receptacle outlets on construction sites, which are not a part of the permanent wiring of the building or structure and which are in use by employees, shall have approved ground-fault circuit interrupters for personnel protection. Receptacles on a two-wire, single-phase portable or vehicle-mounted generator rated not more than 5kW, where the circuit conductors of the generator are insulated from the generator frame and all other grounded surfaces, need not be protected with ground-fault circuit interrupters.
(iii) Assured equipment grounding conductor program. The employer shall establish and implement an assured equipment grounding conductor program on construction sites covering all cord sets, receptacles which are not a part of the building or structure, and equipment connected by cord and plug which are available for use or used by employees. This program shall comply with the following minimum requirements:
(A) A written description of the program, including the specific procedures adopted by the employer, shall be available at the jobsite for inspection and copying by the Assistant Secretary and any affected employee.
(B) The employer shall designate one or more competent persons (as defined in § 1926.32(f)) to implement the program.
(C) Each cord set, attachment cap, plug and receptacle of cord sets, and any equipment connected by cord and plug, except cord sets and receptacles which are fixed and not exposed to damage, shall be visually inspected before each day''s use for external defects, such as deformed or missing pins or insulation damage, and for indications of possible internal damage. Equipment found damaged or defective shall not be used until repaired.
(D) The following tests shall be performed on all cord sets, receptacles which are not a part of the permanent wiring of the building or structure, and cord- and plug-connected equipment required to be grounded:
(1) All equipment grounding conductors shall be tested for continuity and shall be electrically continuous.
(2) Each receptacle and attachment cap or plug shall be tested for correct attachment of the equipment grounding conductor. The equipment grounding conductor shall be connected to its proper terminal.
(E) All required tests shall be performed:
(1) Before first use;
(2) Before equipment is returned to service following any repairs;
(3) Before equipment is used after any incident which can be reasonably suspected to have caused damage (for example, when a cord set is run over); and
(4) At intervals not to exceed 3 months, except that cord sets and receptacles which are fixed and not exposed to damage shall be tested at intervals not exceeding 6 months.
(F) The employer shall not make available or permit the use by employees of any equipment which has not met the requirements of this paragraph (b)(1)(iii) of this section.
(G) Tests performed as required in this paragraph shall be recorded. This test record shall identify each receptacle, cord set, and cord- and plug-connected equipment that passed the test and shall indicate the last date it was tested or the interval for which it was tested. This record shall be kept by means of logs, color coding, or other effective means and shall be maintained until replaced by a more current record. The record shall be made available on the jobsite for inspection by the Assistant Secretary and any affected employee.
(2) Outlet devices. Outlet devices shall have an ampere rating not less than the load to be served and shall comply with the following:
(i) Single receptacles. A single receptacle installed on an individual branch circuit shall have an ampere rating of not less than that of the branch circuit.
(ii) Two or more receptacles. Where connected to a branch circuit supplying two or more receptacles or outlets, receptacle ratings shall conform to the values listed in Table K-4.
(iii) Receptacles used for the connection of motors. The rating of an attachment plug or receptacle used for cord- and plug-connection of a motor to a branch circuit shall not exceed 15 amperes at 125 volts or 10 amperes at 250 volts if individual overload protection is omitted.
Table K-4—Receptacle Ratings for Various Size Circuits', 'On construction sites, temporary 120-volt, single-phase 15- and 20-amp receptacles in use by employees need GFCI protection, or the employer must run an assured equipment grounding conductor program.', null, null, null, null, '{}'::text[], array['gfci', 'ground fault', 'temporary power', 'extension cords']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.404#p-1926.404(b)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '2d736304cd7dc19242567ab03eeee103865b39d5c661e7ee5350e657b6264837', 10),
  (md5('academykb:section:cfr:1926.451(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.451(a)', '29 CFR 1926.451(a)', 'General requirements: Capacity', '29 CFR Part 1926 › § 1926.451 General requirements', 'requirement', 'full_text', '(a) Capacity. (1) Except as provided in paragraphs (a)(2), (a)(3), (a)(4), (a)(5) and (g) of this section, each scaffold and scaffold component shall be capable of supporting, without failure, its own weight and at least 4 times the maximum intended load applied or transmitted to it.
(2) Direct connections to roofs and floors, and counterweights used to balance adjustable suspension scaffolds, shall be capable of resisting at least 4 times the tipping moment imposed by the scaffold operating at the rated load of the hoist, or 1.5 (minimum) times the tipping moment imposed by the scaffold operating at the stall load of the hoist, whichever is greater.
(3) Each suspension rope, including connecting hardware, used on non-adjustable suspension scaffolds shall be capable of supporting, without failure, at least 6 times the maximum intended load applied or transmitted to that rope.
(4) Each suspension rope, including connecting hardware, used on adjustable suspension scaffolds shall be capable of supporting, without failure, at least 6 times the maximum intended load applied or transmitted to that rope with the scaffold operating at either the rated load of the hoist, or 2 (minimum) times the stall load of the hoist, whichever is greater.
(5) The stall load of any scaffold hoist shall not exceed 3 times its rated load.
(6) Scaffolds shall be designed by a qualified person and shall be constructed and loaded in accordance with that design. Non-mandatory appendix A to this subpart contains examples of criteria that will enable an employer to comply with paragraph (a) of this section.', null, null, null, null, null, array['general-contracting', 'masonry', 'painting', 'pressure-washing', 'roofing', 'siding', 'soft-washing']::text[], array['scaffold', 'scaffolding', 'fall protection']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.451#p-1926.451(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '7a2f4ecf6feef9700123a420a98deb288b5bc56cb3713e600fd9de466c345b03', 11),
  (md5('academykb:section:cfr:1926.451(g)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.451(g)', '29 CFR 1926.451(g)', 'General requirements: Fall protection', '29 CFR Part 1926 › § 1926.451 General requirements', 'requirement', 'full_text', '(g) Fall protection. (1) Each employee on a scaffold more than 10 feet (3.1 m) above a lower level shall be protected from falling to that lower level. Paragraphs (g)(1) (i) through (vii) of this section establish the types of fall protection to be provided to the employees on each type of scaffold. Paragraph (g)(2) of this section addresses fall protection for scaffold erectors and dismantlers.
The fall protection requirements for employees installing suspension scaffold support systems on floors, roofs, and other elevated surfaces are set forth in subpart M of this part.
(i) Each employee on a boatswains'' chair, catenary scaffold, float scaffold, needle beam scaffold, or ladder jack scaffold shall be protected by a personal fall arrest system;
(ii) Each employee on a single-point or two-point adjustable suspension scaffold shall be protected by both a personal fall arrest system and guardrail system;
(iii) Each employee on a crawling board (chicken ladder) shall be protected by a personal fall arrest system, a guardrail system (with minimum 200 pound toprail capacity), or by a three-fourth inch (1.9 cm) diameter grabline or equivalent handhold securely fastened beside each crawling board;
(iv) Each employee on a self-contained adjustable scaffold shall be protected by a guardrail system (with minimum 200 pound toprail capacity) when the platform is supported by the frame structure, and by both a personal fall arrest system and a guardrail system (with minimum 200 pound toprail capacity) when the platform is supported by ropes;
(v) Each employee on a walkway located within a scaffold shall be protected by a guardrail system (with minimum 200 pound toprail capacity) installed within 9 1/2 inches (24.1 cm) of and along at least one side of the walkway.
(vi) Each employee performing overhand bricklaying operations from a supported scaffold shall be protected from falling from all open sides and ends of the scaffold (except at the side next to the wall being laid) by the use of a personal fall arrest system or guardrail system (with minimum 200 pound toprail capacity).
(vii) For all scaffolds not otherwise specified in paragraphs (g)(1)(i) through (g)(1)(vi) of this section, each employee shall be protected by the use of personal fall arrest systems or guardrail systems meeting the requirements of paragraph (g)(4) of this section.
(2) Effective September 2, 1997, the employer shall have a competent person determine the feasibility and safety of providing fall protection for employees erecting or dismantling supported scaffolds. Employers are required to provide fall protection for employees erecting or dismantling supported scaffolds where the installation and use of such protection is feasible and does not create a greater hazard.
(3) In addition to meeting the requirements of § 1926.502(d), personal fall arrest systems used on scaffolds shall be attached by lanyard to a vertical lifeline, horizontal lifeline, or scaffold structural member. Vertical lifelines shall not be used when overhead components, such as overhead protection or additional platform levels, are part of a single-point or two-point adjustable suspension scaffold.
(i) When vertical lifelines are used, they shall be fastened to a fixed safe point of anchorage, shall be independent of the scaffold, and shall be protected from sharp edges and abrasion. Safe points of anchorage include structural members of buildings, but do not include standpipes, vents, other piping systems, electrical conduit, outrigger beams, or counterweights.
(ii) When horizontal lifelines are used, they shall be secured to two or more structural members of the scaffold, or they may be looped around both suspension and independent suspension lines (on scaffolds so equipped) above the hoist and brake attached to the end of the scaffold. Horizontal lifelines shall not be attached only to the suspension ropes.
(iii) When lanyards are connected to horizontal lifelines or structural members on a single-point or two-point adjustable suspension scaffold, the scaffold shall be equipped with additional independent support lines and automatic locking devices capable of stopping the fall of the scaffold in the event one or both of the suspension ropes fail. The independent support lines shall be equal in number and strength to the suspension ropes.
(iv) Vertical lifelines, independent support lines, and suspension ropes shall not be attached to each other, nor shall they be attached to or use the same point of anchorage, nor shall they be attached to the same point on the scaffold or personal fall arrest system.
(4) Guardrail systems installed to meet the requirements of this section shall comply with the following provisions (guardrail systems built in accordance with appendix A to this subpart will be deemed to meet the requirements of paragraphs (g)(4) (vii), (viii), and (ix) of this section):
(i) Guardrail systems shall be installed along all open sides and ends of platforms. Guardrail systems shall be installed before the scaffold is released for use by employees other than erection/dismantling crews.
(ii) The top edge height of toprails or equivalent member on supported scaffolds manufactured or placed in service after January 1, 2000 shall be installed between 38 inches (0.97 m) and 45 inches (1.2 m) above the platform surface. The top edge height on supported scaffolds manufactured and placed in service before January 1, 2000, and on all suspended scaffolds where both a guardrail and a personal fall arrest system are required shall be between 36 inches (0.9 m) and 45 inches (1.2 m). When conditions warrant, the height of the top edge may exceed the 45-inch height, provided the guardrail system meets all other criteria of paragraph (g)(4).
(iii) When midrails, screens, mesh, intermediate vertical members, solid panels, or equivalent structural members are used, they shall be installed between the top edge of the guardrail system and the scaffold platform.
(iv) When midrails are used, they shall be installed at a height approximately midway between the top edge of the guardrail system and the platform surface.
(v) When screens and mesh are used, they shall extend from the top edge of the guardrail system to the scaffold platform, and along the entire opening between the supports.
(vi) When intermediate members (such as balusters or additional rails) are used, they shall not be more than 19 inches (48 cm) apart.
(vii) Each toprail or equivalent member of a guardrail system shall be capable of withstanding, without failure, a force applied in any downward or horizontal direction at any point along its top edge of at least 100 pounds (445 n) for guardrail systems installed on single-point adjustable suspension scaffolds or two-point adjustable suspension scaffolds, and at least 200 pounds (890 n) for guardrail systems installed on all other scaffolds.
(viii) When the loads specified in paragraph (g)(4)(vii) of this section are applied in a downward direction, the top edge shall not drop below the height above the platform surface that is prescribed in paragraph (g)(4)(ii) of this section.
(ix) Midrails, screens, mesh, intermediate vertical members, solid panels, and equivalent structural members of a guardrail system shall be capable of withstanding, without failure, a force applied in any downward or horizontal direction at any point along the midrail or other member of at least 75 pounds (333 n) for guardrail systems with a minimum 100 pound toprail capacity, and at least 150 pounds (666 n) for guardrail systems with a minimum 200 pound toprail capacity.
(x) Suspension scaffold hoists and non-walk-through stirrups may be used as end guardrails, if the space between the hoist or stirrup and the side guardrail or structure does not allow passage of an employee to the end of the scaffold.
(xi) Guardrails shall be surfaced to prevent injury to an employee from punctures or lacerations, and to prevent snagging of clothing.
(xii) The ends of all rails shall not overhang the terminal posts except when such overhang does not constitute a projection hazard to employees.
(xiii) Steel or plastic banding shall not be used as a toprail or midrail.
(xiv) Manila or plastic (or other synthetic) rope being used for toprails or midrails shall be inspected by a competent person as frequently as necessary to ensure that it continues to meet the strength requirements of paragraph (g) of this section.
(xv) Crossbracing is acceptable in place of a midrail when the crossing point of two braces is between 20 inches (0.5 m) and 30 inches (0.8 m) above the work platform or as a toprail when the crossing point of two braces is between 38 inches (0.97 m) and 48 inches (1.3 m) above the work platform. The end points at each upright shall be no more than 48 inches (1.3 m) apart.', 'Workers on a scaffold more than 10 feet above a lower level must be protected from falling, with the type of protection depending on the scaffold.', null, null, null, null, array['general-contracting', 'masonry', 'painting', 'pressure-washing', 'roofing', 'siding', 'soft-washing']::text[], array['scaffold', 'scaffolding', 'fall protection']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.451#p-1926.451(g)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '45245b74dc3020f7e4a743ee301e509be162ed66482a5205099b39ad350893a5', 12),
  (md5('academykb:section:cfr:1926.501(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.501(a)', '29 CFR 1926.501(a)', 'Duty to have fall protection: General', '29 CFR Part 1926 › § 1926.501 Duty to have fall protection', 'requirement', 'full_text', '(a) General. (1) This section sets forth requirements for employers to provide fall protection systems. All fall protection required by this section shall conform to the criteria set forth in § 1926.502 of this subpart.
(2) The employer shall determine if the walking/working surfaces on which its employees are to work have the strength and structural integrity to support employees safely. Employees shall be allowed to work on those surfaces only when the surfaces have the requisite strength and structural integrity.', 'Sets out when employers must provide fall protection and that the systems must meet 29 CFR 1926.502.', null, null, null, null, '{}'::text[], array['fall protection', 'roof edge', 'guardrail', 'residential construction', 'low-slope roof', 'steep roof', 'holes', 'excavation edge']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.501#p-1926.501(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'c6c05b7f58c4bad94096543880b1941cad40c18487726f57a53df2f02fa73d3c', 13),
  (md5('academykb:section:cfr:1926.501(b)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.501(b)', '29 CFR 1926.501(b)', 'Duty to have fall protection: paragraph (b)', '29 CFR Part 1926 › § 1926.501 Duty to have fall protection', 'requirement', 'full_text', '(b)(1) Unprotected sides and edges. Each employee on a walking/working surface (horizontal and vertical surface) with an unprotected side or edge which is 6 feet (1.8 m) or more above a lower level shall be protected from falling by the use of guardrail systems, safety net systems, or personal fall arrest systems.
(2) Leading edges. (i) Each employee who is constructing a leading edge 6 feet (1.8 m) or more above lower levels shall be protected from falling by guardrail systems, safety net systems, or personal fall arrest systems. Exception: When the employer can demonstrate that it is infeasible or creates a greater hazard to use these systems, the employer shall develop and implement a fall protection plan which meets the requirements of paragraph (k) of § 1926.502.
There is a presumption that it is feasible and will not create a greater hazard to implement at least one of the above-listed fall protection systems. Accordingly, the employer has the burden of establishing that it is appropriate to implement a fall protection plan which complies with § 1926.502(k) for a particular workplace situation, in lieu of implementing any of those systems.
(ii) Each employee on a walking/working surface 6 feet (1.8 m) or more above a lower level where leading edges are under construction, but who is not engaged in the leading edge work, shall be protected from falling by a guardrail system, safety net system, or personal fall arrest system. If a guardrail system is chosen to provide the fall protection, and a controlled access zone has already been established for leading edge work, the control line may be used in lieu of a guardrail along the edge that parallels the leading edge.
(3) Hoist areas. Each employee in a hoist area shall be protected from falling 6 feet (1.8 m) or more to lower levels by guardrail systems or personal fall arrest systems. If guardrail systems, [or chain, gate, or guardrail] or portions thereof, are removed to facilitate the hoisting operation (e.g., during landing of materials), and an employee must lean through the access opening or out over the edge of the access opening (to receive or guide equipment and materials, for example), that employee shall be protected from fall hazards by a personal fall arrest system.
(4) Holes. (i) Each employee on walking/working surfaces shall be protected from falling through holes (including skylights) more than 6 feet (1.8 m) above lower levels, by personal fall arrest systems, covers, or guardrail systems erected around such holes.
(ii) Each employee on a walking/working surface shall be protected from tripping in or stepping into or through holes (including skylights) by covers.
(iii) Each employee on a walking/working surface shall be protected from objects falling through holes (including skylights) by covers.
(5) Formwork and reinforcing steel. Each employee on the face of formwork or reinforcing steel shall be protected from falling 6 feet (1.8 m) or more to lower levels by personal fall arrest systems, safety net systems, or positioning device systems.
(6) Ramps, runways, and other walkways. Each employee on ramps, runways, and other walkways shall be protected from falling 6 feet (1.8 m) or more to lower levels by guardrail systems.
(7) Excavations. (i) Each employee at the edge of an excavation 6 feet (1.8 m) or more in depth shall be protected from falling by guardrail systems, fences, or barricades when the excavations are not readily seen because of plant growth or other visual barrier;
(ii) Each employee at the edge of a well, pit, shaft, and similar excavation 6 feet (1.8 m) or more in depth shall be protected from falling by guardrail systems, fences, barricades, or covers.
(8) Dangerous equipment. (i) Each employee less than 6 feet (1.8 m) above dangerous equipment shall be protected from falling into or onto the dangerous equipment by guardrail systems or by equipment guards.
(ii) Each employee 6 feet (1.8 m) or more above dangerous equipment shall be protected from fall hazards by guardrail systems, personal fall arrest systems, or safety net systems.
(9) Overhand bricklaying and related work. (i) Except as otherwise provided in paragraph (b) of this section, each employee performing overhand bricklaying and related work 6 feet (1.8 m) or more above lower levels, shall be protected from falling by guardrail systems, safety net systems, personal fall arrest systems, or shall work in a controlled access zone.
(ii) Each employee reaching more than 10 inches (25 cm) below the level of the walking/working surface on which they are working, shall be protected from falling by a guardrail system, safety net system, or personal fall arrest system.
Bricklaying operations performed on scaffolds are regulated by subpart L—Scaffolds of this part.
(10) Roofing work on Low-slope roofs. Except as otherwise provided in paragraph (b) of this section, each employee engaged in roofing activities on low-slope roofs, with unprotected sides and edges 6 feet (1.8 m) or more above lower levels shall be protected from falling by guardrail systems, safety net systems, personal fall arrest systems, or a combination of warning line system and guardrail system, warning line system and safety net system, or warning line system and personal fall arrest system, or warning line system and safety monitoring system. Or, on roofs 50-feet (15.25 m) or less in width (see appendix A to subpart M of this part), the use of a safety monitoring system alone [i.e. without the warning line system] is permitted.
(11) Steep roofs. Each employee on a steep roof with unprotected sides and edges 6 feet (1.8 m) or more above lower levels shall be protected from falling by guardrail systems with toeboards, safety net systems, or personal fall arrest systems.
(12) Precast concrete erection. Each employee engaged in the erection of precast concrete members (including, but not limited to the erection of wall panels, columns, beams, and floor and roof “tees”) and related operations such as grouting of precast concrete members, who is 6 feet (1.8 m) or more above lower levels shall be protected from falling by guardrail systems, safety net systems, or personal fall arrest systems, unless another provision in paragraph (b) of this section provides for an alternative fall protection measure. Exception: When the employer can demonstrate that it is infeasible or creates a greater hazard to use these systems, the employer shall develop and implement a fall protection plan which meets the requirements of paragraph (k) of § 1926.502.
There is a presumption that it is feasible and will not create a greater hazard to implement at least one of the above-listed fall protection systems. Accordingly, the employer has the burden of establishing that it is appropriate to implement a fall protection plan which complies with § 1926.502(k) for a particular workplace situation, in lieu of implementing any of those systems.
(13) Residential construction. Each employee engaged in residential construction activities 6 feet (1.8 m) or more above lower levels shall be protected by guardrail systems, safety net system, or personal fall arrest system unless another provision in paragraph (b) of this section provides for an alternative fall protection measure. Exception: When the employer can demonstrate that it is infeasible or creates a greater hazard to use these systems, the employer shall develop and implement a fall protection plan which meets the requirements of paragraph (k) of § 1926.502.
There is a presumption that it is feasible and will not create a greater hazard to implement at least one of the above-listed fall protection systems. Accordingly, the employer has the burden of establishing that it is appropriate to implement a fall protection plan which complies with § 1926.502(k) for a particular workplace situation, in lieu of implementing any of those systems.
(14) Wall openings. Each employee working on, at, above, or near wall openings (including those with chutes attached) where the outside bottom edge of the wall opening is 6 feet (1.8 m) or more above lower levels and the inside bottom edge of the wall opening is less than 39 inches (1.0 m) above the walking/working surface, shall be protected from falling by the use of a guardrail system, a safety net system, or a personal fall arrest system.
(15) Walking/working surfaces not otherwise addressed. Except as provided in § 1926.500(a)(2) or in § 1926.501 (b)(1) through (b)(14), each employee on a walking/working surface 6 feet (1.8 m) or more above lower levels shall be protected from falling by a guardrail system, safety net system, or personal fall arrest system.', 'Employers must protect workers from falls of 6 feet or more to a lower level, using guardrails, safety nets or personal fall arrest systems, with specific options for leading edges, holes, low-slope and steep roofs, and residential construction (where a written fall protection plan is allowed only when the employer can show the usual systems are infeasible or more hazardous).', null, null, null, null, '{}'::text[], array['fall protection', 'roof edge', 'guardrail', 'residential construction', 'low-slope roof', 'steep roof', 'holes', 'excavation edge']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.501#p-1926.501(b)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'e020efe18567e5ef8cf5cc64e9c7ae469c40ff936443305c15fd79ef650f454f', 14),
  (md5('academykb:section:cfr:1926.501(c)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.501(c)', '29 CFR 1926.501(c)', 'Duty to have fall protection: Protection from falling objects', '29 CFR Part 1926 › § 1926.501 Duty to have fall protection', 'requirement', 'full_text', '(c) Protection from falling objects. When an employee is exposed to falling objects, the employer shall have each employee wear a hard hat and shall implement one of the following measures:
(1) Erect toeboards, screens, or guardrail systems to prevent objects from falling from higher levels; or,
(2) Erect a canopy structure and keep potential fall objects far enough from the edge of the higher level so that those objects would not go over the edge if they were accidentally displaced; or,
(3) Barricade the area to which objects could fall, prohibit employees from entering the barricaded area, and keep objects that may fall far enough away from the edge of a higher level so that those objects would not go over the edge if they were accidentally displaced.', null, null, null, null, null, '{}'::text[], array['fall protection', 'roof edge', 'guardrail', 'residential construction', 'low-slope roof', 'steep roof', 'holes', 'excavation edge']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.501#p-1926.501(c)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '7193e1018660fb59d4050e82bc1d9e722b7981c59f1faa38ec763d78d14f33db', 15),
  (md5('academykb:section:cfr:1926.502(b)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.502(b)', '29 CFR 1926.502(b)', 'Fall protection systems criteria and practices: Guardrail systems', '29 CFR Part 1926 › § 1926.502 Fall protection systems criteria and practices', 'requirement', 'full_text', '(b) Guardrail systems. Guardrail systems and their use shall comply with the following provisions:
(1) Top edge height of top rails, or equivalent guardrail system members, shall be 42 inches (1.1 m) plus or minus 3 inches (8 cm) above the walking/working level. When conditions warrant, the height of the top edge may exceed the 45-inch height, provided the guardrail system meets all other criteria of this paragraph.
When employees are using stilts, the top edge height of the top rail, or equivalent member, shall be increased an amount equal to the height of the stilts.
(2) Midrails, screens, mesh, intermediate vertical members, or equivalent intermediate structural members shall be installed between the top edge of the guardrail system and the walking/working surface when there is no wall or parapet wall at least 21 inches (53 cm) high.
(i) Midrails, when used, shall be installed at a height midway between the top edge of the guardrail system and the walking/working level.
(ii) Screens and mesh, when used, shall extend from the top rail to the walking/working level and along the entire opening between top rail supports.
(iii) Intermediate members (such as balusters), when used between posts, shall be not more than 19 inches (48 cm) apart.
(iv) Other structural members (such as additional midrails and architectural panels) shall be installed such that there are no openings in the guardrail system that are more than 19 inches (.5 m) wide.
(3) Guardrail systems shall be capable of withstanding, without failure, a force of at least 200 pounds (890 N) applied within 2 inches (5.1 cm) of the top edge, in any outward or downward direction, at any point along the top edge.
(4) When the 200 pound (890 N) test load specified in paragraph (b)(3) of this section is applied in a downward direction, the top edge of the guardrail shall not deflect to a height less than 39 inches (1.0 m) above the walking/working level. Guardrail system components selected and constructed in accordance with the appendix B to subpart M of this part will be deemed to meet this requirement.
(5) Midrails, screens, mesh, intermediate vertical members, solid panels, and equivalent structural members shall be capable of withstanding, without failure, a force of at least 150 pounds (666 N) applied in any downward or outward direction at any point along the midrail or other member.
(6) Guardrail systems shall be so surfaced as to prevent injury to an employee from punctures or lacerations, and to prevent snagging of clothing.
(7) The ends of all top rails and midrails shall not overhang the terminal posts, except where such overhang does not constitute a projection hazard.
(8) Steel banding and plastic banding shall not be used as top rails or midrails.
(9) Top rails and midrails shall be at least one-quarter inch (0.6 cm) nominal diameter or thickness to prevent cuts and lacerations. If wire rope is used for top rails, it shall be flagged at not more than 6-foot (1.8 m) intervals with high-visibility material.
(10) When guardrail systems are used at hoisting areas, a chain, gate or removable guardrail section shall be placed across the access opening between guardrail sections when hoisting operations are not taking place.
(11) When guardrail systems are used at holes, they shall be erected on all unprotected sides or edges of the hole.
(12) When guardrail systems are used around holes used for the passage of materials, the hole shall have not more than two sides provided with removable guardrail sections to allow the passage of materials. When the hole is not in use, it shall be closed over with a cover, or a guardrail system shall be provided along all unprotected sides or edges.
(13) When guardrail systems are used around holes which are used as points of access (such as ladderways), they shall be provided with a gate, or be so offset that a person cannot walk directly into the hole.
(14) Guardrail systems used on ramps and runways shall be erected along each unprotected side or edge.
(15) Manila, plastic or synthetic rope being used for top rails or midrails shall be inspected as frequently as necessary to ensure that it continues to meet the strength requirements of paragraph (b)(3) of this section.', 'Guardrail systems: the top edge of the top rail must be 42 inches, plus or minus 3 inches, above the walking/working level, with midrails or equivalent and strength requirements.', null, null, null, null, '{}'::text[], array['guardrail', 'guardrail height', 'personal fall arrest', 'harness', 'anchorage', 'fall protection plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.502#p-1926.502(b)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '224f9737f6727e478f4dfe06517ac0c2a3dbecb912d93cf6883f6ace79853b1a', 16),
  (md5('academykb:section:cfr:1926.502(d)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.502(d)', '29 CFR 1926.502(d)', 'Fall protection systems criteria and practices: Personal fall arrest systems', '29 CFR Part 1926 › § 1926.502 Fall protection systems criteria and practices', 'requirement', 'full_text', '(d) Personal fall arrest systems. Personal fall arrest systems and their use shall comply with the provisions set forth below. Effective January 1, 1998, body belts are not acceptable as part of a personal fall arrest system. Note: The use of a body belt in a positioning device system is acceptable and is regulated under paragraph (e) of this section.
(1) Connectors shall be drop forged, pressed or formed steel, or made of equivalent materials.
(2) Connectors shall have a corrosion-resistant finish, and all surfaces and edges shall be smooth to prevent damage to interfacing parts of the system.
(3) Dee-rings and snaphooks shall have a minimum tensile strength of 5,000 pounds (22.2 kN).
(4) Dee-rings and snaphooks shall be proof-tested to a minimum tensile load of 3,600 pounds (16 kN) without cracking, breaking, or taking permanent deformation.
(5) Snaphooks shall be sized to be compatible with the member to which they are connected to prevent unintentional disengagement of the snaphook by depression of the snaphook keeper by the connected member, or shall be a locking type snaphook designed and used to prevent disengagement of the snaphook by the contact of the snaphook keeper by the connected member. Effective January 1, 1998, only locking type snaphooks shall be used.
(6) Unless the snaphook is a locking type and designed for the following connections, snaphooks shall not be engaged:
(i) directly to webbing, rope or wire rope;
(ii) to each other;
(iii) to a Dee-ring to which another snaphook or other connector is attached;
(iv) to a horizontal lifeline; or
(v) to any object which is incompatibly shaped or dimensioned in relation to the snaphook such that unintentional disengagement could occur by the connected object being able to depress the snaphook keeper and release itself.
(7) On suspended scaffolds or similar work platforms with horizontal lifelines which may become vertical lifelines, the devices used to connect to a horizontal lifeline shall be capable of locking in both directions on the lifeline.
(8) Horizontal lifelines shall be designed, installed, and used, under the supervision of a qualified person, as part of a complete personal fall arrest system, which maintains a safety factor of at least two.
(9) Lanyards and vertical lifelines shall have a minimum breaking strength of 5,000 pounds (22.2 kN).
(10) (i) Except as provided in paragraph (d)(10)(ii) of this section, when vertical lifelines are used, each employee shall be attached to a separate lifeline.
(ii) During the construction of elevator shafts, two employees may be attached to the same lifeline in the hoistway, provided both employees are working atop a false car that is equipped with guardrails; the strength of the lifeline is 10,000 pounds [5,000 pounds per employee attached] (44.4 kN); and all other criteria specified in this paragraph for lifelines have been met.
(11) Lifelines shall be protected against being cut or abraded.
(12) Self-retracting lifelines and lanyards which automatically limit free fall distance to 2 feet (0.61 m) or less shall be capable of sustaining a minimum tensile load of 3,000 pounds (13.3 kN) applied to the device with the lifeline or lanyard in the fully extended position.
(13) Self-retracting lifelines and lanyards which do not limit free fall distance to 2 feet (0.61 m) or less, ripstitch lanyards, and tearing and deforming lanyards shall be capable of sustaining a minimum tensile load of 5,000 pounds (22.2 kN) applied to the device with the lifeline or lanyard in the fully extended position.
(14) Ropes and straps (webbing) used in lanyards, lifelines, and strength components of body belts and body harnesses shall be made from synthetic fibers.
(15) Anchorages used for attachment of personal fall arrest equipment shall be independent of any anchorage being used to support or suspend platforms and capable of supporting at least 5,000 pounds (22.2 kN) per employee attached, or shall be designed, installed, and used as follows:
(i) as part of a complete personal fall arrest system which maintains a safety factor of at least two; and
(ii) under the supervision of a qualified person.
(16) Personal fall arrest systems, when stopping a fall, shall:
(i) limit maximum arresting force on an employee to 900 pounds (4 kN) when used with a body belt;
(ii) limit maximum arresting force on an employee to 1,800 pounds (8 kN) when used with a body harness;
(iii) be rigged such that an employee can neither free fall more than 6 feet (1.8 m), nor contact any lower level;
(iv) bring an employee to a complete stop and limit maximum deceleration distance an employee travels to 3.5 feet (1.07 m); and,
(v) have sufficient strength to withstand twice the potential impact energy of an employee free falling a distance of 6 feet (1.8 m), or the free fall distance permitted by the system, whichever is less.
If the personal fall arrest system meets the criteria and protocols contained in appendix C to subpart M, and if the system is being used by an employee having a combined person and tool weight of less than 310 pounds (140 kg), the system will be considered to be in compliance with the provisions of paragraph (d)(16) of this section. If the system is used by an employee having a combined tool and body weight of 310 pounds (140 kg) or more, then the employer must appropriately modify the criteria and protocols of the appendix to provide proper protection for such heavier weights, or the system will not be deemed to be in compliance with the requirements of paragraph (d)(16) of this section.
(17) The attachment point of the body belt shall be located in the center of the wearer''s back. The attachment point of the body harness shall be located in the center of the wearer''s back near shoulder level, or above the wearer''s head.
(18) Body belts, harnesses, and components shall be used only for employee protection (as part of a personal fall arrest system or positioning device system) and not to hoist materials.
(19) Personal fall arrest systems and components subjected to impact loading shall be immediately removed from service and shall not be used again for employee protection until inspected and determined by a competent person to be undamaged and suitable for reuse.
(20) The employer shall provide for prompt rescue of employees in the event of a fall or shall assure that employees are able to rescue themselves.
(21) Personal fall arrest systems shall be inspected prior to each use for wear, damage and other deterioration, and defective components shall be removed from service.
(22) Body belts shall be at least one and five-eighths (1 5/8 ) inches (4.1 cm) wide.
(23) Personal fall arrest systems shall not be attached to guardrail systems, nor shall they be attached to hoists except as specified in other subparts of this part.
(24) When a personal fall arrest system is used at hoist areas, it shall be rigged to allow the movement of the employee only as far as the edge of the walking/working surface.', 'Personal fall arrest systems: anchorages, connectors, harnesses and lanyards must meet strength and use requirements, and the system must limit free fall and arrest forces.', null, null, null, null, '{}'::text[], array['guardrail', 'guardrail height', 'personal fall arrest', 'harness', 'anchorage', 'fall protection plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.502#p-1926.502(d)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '85708791f65b604eee0ceb62d035fc971036242e16535abc0b593f595fb817ae', 17),
  (md5('academykb:section:cfr:1926.502(k)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.502(k)', '29 CFR 1926.502(k)', 'Fall protection systems criteria and practices: Fall protection plan', '29 CFR Part 1926 › § 1926.502 Fall protection systems criteria and practices', 'requirement', 'full_text', '(k) Fall protection plan. This option is available only to employees engaged in leading edge work, precast concrete erection work, or residential construction work (See § 1926.501(b)(2), (b)(12), and (b)(13)) who can demonstrate that it is infeasible or it creates a greater hazard to use conventional fall protection equipment. The fall protection plan must conform to the following provisions.
(1) The fall protection plan shall be prepared by a qualified person and developed specifically for the site where the leading edge work, precast concrete work, or residential construction work is being performed and the plan must be maintained up to date.
(2) Any changes to the fall protection plan shall be approved by a qualified person.
(3) A copy of the fall protection plan with all approved changes shall be maintained at the job site.
(4) The implementation of the fall protection plan shall be under the supervision of a competent person.
(5) The fall protection plan shall document the reasons why the use of conventional fall protection systems (guardrail systems, personal fall arrest systems, or safety nets systems) are infeasible or why their use would create a greater hazard.
(6) The fall protection plan shall include a written discussion of other measures that will be taken to reduce or eliminate the fall hazard for workers who cannot be provided with protection from the conventional fall protection systems. For example, the employer shall discuss the extent to which scaffolds, ladders, or vehicle mounted work platforms can be used to provide a safer working surface and thereby reduce the hazard of falling.
(7) The fall protection plan shall identify each location where conventional fall protection methods cannot be used. These locations shall then be classified as controlled access zones and the employer must comply with the criteria in paragraph (g) of this section.
(8) Where no other alternative measure has been implemented, the employer shall implement a safety monitoring system in conformance with § 1926.502(h).
(9) The fall protection plan must include a statement which provides the name or other method of identification for each employee who is designated to work in controlled access zones. No other employees may enter controlled access zones.
(10) In the event an employee falls, or some other related, serious incident occurs, (e.g., a near miss) the employer shall investigate the circumstances of the fall or other incident to determine if the fall protection plan needs to be changed (e.g. new practices, procedures, or training) and shall implement those changes to prevent similar types of falls or incidents.', 'A fall protection plan is an option only for leading-edge work, precast concrete erection or residential construction when the employer can show conventional fall protection is infeasible or creates a greater hazard. It must be written by a qualified person and kept at the job site.', null, null, null, null, '{}'::text[], array['guardrail', 'guardrail height', 'personal fall arrest', 'harness', 'anchorage', 'fall protection plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.502#p-1926.502(k)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '202bfc92aed1b9a638855217a2084298d030183aadea076f697a46d70d2cd398', 18),
  (md5('academykb:section:cfr:1926.503')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.503', '29 CFR 1926.503', 'Training requirements', '29 CFR Part 1926 › § 1926.503 Training requirements', 'requirement', 'full_text', 'The following training provisions supplement and clarify the requirements of § 1926.21 regarding the hazards addressed in subpart M of this part.
(a) Training program. (1) The employer shall provide a training program for each employee who might be exposed to fall hazards. The program shall enable each employee to recognize the hazards of falling and shall train each employee in the procedures to be followed in order to minimize these hazards.
(2) The employer shall assure that each employee has been trained, as necessary, by a competent person qualified in the following areas:
(i) The nature of fall hazards in the work area;
(ii) The correct procedures for erecting, maintaining, disassembling, and inspecting the fall protection systems to be used;
(iii) The use and operation of guardrail systems, personal fall arrest systems, safety net systems, warning line systems, safety monitoring systems, controlled access zones, and other protection to be used;
(iv) The role of each employee in the safety monitoring system when this system is used;
(v) The limitations on the use of mechanical equipment during the performance of roofing work on low-sloped roofs;
(vi) The correct procedures for the handling and storage of equipment and materials and the erection of overhead protection; and
(vii) The role of employees in fall protection plans;
(viii) The standards contained in this subpart.
(b) Certification of training. (1) The employer shall verify compliance with paragraph (a) of this section by preparing a written certification record. The written certification record shall contain the name or other identity of the employee trained, the date(s) of the training, and the signature of the person who conducted the training or the signature of the employer. If the employer relies on training conducted by another employer or completed prior to the effective date of this section, the certification record shall indicate the date the employer determined the prior training was adequate rather than the date of actual training.
(2) The latest training certification shall be maintained.
(c) Retraining. When the employer has reason to believe that any affected employee who has already been trained does not have the understanding and skill required by paragraph (a) of this section, the employer shall retrain each such employee. Circumstances where retraining is required include, but are not limited to, situations where:
(1) Changes in the workplace render previous training obsolete; or
(2) Changes in the types of fall protection systems or equipment to be used render previous training obsolete; or
(3) Inadequacies in an affected employee''s knowledge or use of fall protection systems or equipment indicate that the employee has not retained the requisite understanding or skill.
The following appendices to subpart M of this part serve as non-mandatory guidelines to assist employers in complying with the appropriate requirements of subpart M of this part.', 'Employers must train each worker who might be exposed to fall hazards, by a competent person, and keep a written certification of that training.', null, null, null, null, '{}'::text[], array['fall protection training', 'training']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.503', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '421fdab4901bbfa6645f782a4ec3daf6ef7f2796e35428bf7588efcd638fccb9', 19),
  (md5('academykb:section:cfr:1926.651(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(a)', '29 CFR 1926.651(a)', 'Specific excavation requirements: Surface encumbrances', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(a) Surface encumbrances. All surface encumbrances that are located so as to create a hazard to employees shall be removed or supported, as necessary, to safeguard employees.', null, null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '247cef0f707955b6e1e804a00ea93be2d3e035c660d93d784a448cd5c2e01dbb', 20),
  (md5('academykb:section:cfr:1926.651(b)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(b)', '29 CFR 1926.651(b)', 'Specific excavation requirements: Underground installations', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(b) Underground installations. (1) The estimated location of utility installations, such as sewer, telephone, fuel, electric, water lines, or any other underground installations that reasonably may be expected to be encountered during excavation work, shall be determined prior to opening an excavation.
(2) Utility companies or owners shall be contacted within established or customary local response times, advised of the proposed work, and asked to establish the location of the utility underground installations prior to the start of actual excavation. When utility companies or owners cannot respond to a request to locate underground utility installations within 24 hours (unless a longer period is required by state or local law), or cannot establish the exact location of these installations, the employer may proceed, provided the employer does so with caution, and provided detection equipment or other acceptable means to locate utility installations are used.
(3) When excavation operations approach the estimated location of underground installations, the exact location of the installations shall be determined by safe and acceptable means.
(4) While the excavation is open, underground installations shall be protected, supported or removed as necessary to safeguard employees.', 'Before digging, the estimated location of underground utilities must be determined, and utility companies contacted within established or customary local response times.', null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(b)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '729d6d370dea6427c2bcce98096ab0914b09a6f5ac15c46dc25cd34dbf295878', 21),
  (md5('academykb:section:cfr:1926.651(c)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(c)', '29 CFR 1926.651(c)', 'Specific excavation requirements: Access and egress', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(c) Access and egress—(1) Structural ramps. (i) Structural ramps that are used solely by employees as a means of access or egress from excavations shall be designed by a competent person. Structural ramps used for access or egress of equipment shall be designed by a competent person qualified in structural design, and shall be constructed in accordance with the design.
(ii) Ramps and runways constructed of two or more structural members shall have the structural members connected together to prevent displacement.
(iii) Structural members used for ramps and runways shall be of uniform thickness.
(iv) Cleats or other appropriate means used to connect runway structural members shall be attached to the bottom of the runway or shall be attached in a manner to prevent tripping.
(v) Structural ramps used in lieu of steps shall be provided with cleats or other surface treatments on the top surface to prevent slipping.
(2) Means of egress from trench excavations. A stairway, ladder, ramp or other safe means of egress shall be located in trench excavations that are 4 feet (1.22 m) or more in depth so as to require no more than 25 feet (7.62 m) of lateral travel for employees.', null, null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(c)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '74ddbe16c470f9565b496496edf9aceccb35bf6c3d11a90c429ec46d9b6d18bd', 22),
  (md5('academykb:section:cfr:1926.651(d)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(d)', '29 CFR 1926.651(d)', 'Specific excavation requirements: Exposure to vehicular traffic', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(d) Exposure to vehicular traffic. Employees exposed to public vehicular traffic shall be provided with, and shall wear, warning vests or other suitable garments marked with or made of reflectorized or high-visibility material.', null, null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(d)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '7219b435197b4f69d099b3416f5d9c82541842da6f180d1927ea90427096dc3c', 23),
  (md5('academykb:section:cfr:1926.651(e)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(e)', '29 CFR 1926.651(e)', 'Specific excavation requirements: Exposure to falling loads', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(e) Exposure to falling loads. No employee shall be permitted underneath loads handled by lifting or digging equipment. Employees shall be required to stand away from any vehicle being loaded or unloaded to avoid being struck by any spillage or falling materials. Operators may remain in the cabs of vehicles being loaded or unloaded when the vehicles are equipped, in accordance with § 1926.601(b)(6), to provide adequate protection for the operator during loading and unloading operations.', null, null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(e)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'd5f62ac60ad02d2ce4e064fb3897836bfa049ce42468d3fc287f9291d8dacee2', 24),
  (md5('academykb:section:cfr:1926.651(f)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(f)', '29 CFR 1926.651(f)', 'Specific excavation requirements: Warning system for mobile equipment', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(f) Warning system for mobile equipment. When mobile equipment is operated adjacent to an excavation, or when such equipment is required to approach the edge of an excavation, and the operator does not have a clear and direct view of the edge of the excavation, a warning system shall be utilized such as barricades, hand or mechanical signals, or stop logs. If possible, the grade should be away from the excavation.', null, null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(f)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '95c0029d319b042e0545ee425fd7c494e1fb10db3d6e3c6306b913a689da237e', 25),
  (md5('academykb:section:cfr:1926.651(g)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(g)', '29 CFR 1926.651(g)', 'Specific excavation requirements: Hazardous atmospheres', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(g) Hazardous atmospheres—(1) Testing and controls. In addition to the requirements set forth in subparts D and E of this part (29 CFR 1926.50-1926.107) to prevent exposure to harmful levels of atmospheric contaminants and to assure acceptable atmospheric conditions, the following requirements shall apply:
(i) Where oxygen deficiency (atmospheres containing less than 19.5 percent oxygen) or a hazardous atmosphere exists or could reasonably be expected to exist, such as in excavations in landfill areas or excavations in areas where hazardous substances are stored nearby, the atmospheres in the excavation shall be tested before employees enter excavations greater than 4 feet (1.22 m) in depth.
(ii) Adequate precautions shall be taken to prevent employee exposure to atmospheres containing less than 19.5 percent oxygen and other hazardous atmospheres. These precautions include providing proper respiratory protection or ventilation in accordance with subparts D and E of this part respectively.
(iii) Adequate precaution shall be taken such as providing ventilation, to prevent employee exposure to an atmosphere containing a concentration of a flammable gas in excess of 20 percent of the lower flammable limit of the gas.
(iv) When controls are used that are intended to reduce the level of atmospheric contaminants to acceptable levels, testing shall be conducted as often as necessary to ensure that the atmosphere remains safe.
(2) Emergency rescue equipment. (i) Emergency rescue equipment, such as breathing apparatus, a safety harness and line, or a basket stretcher, shall be readily available where hazardous atmospheric conditions exist or may reasonably be expected to develop during work in an excavation. This equipment shall be attended when in use.
(ii) Employees entering bell-bottom pier holes, or other similar deep and confined footing excavations, shall wear a harness with a life-line securely attached to it. The lifeline shall be separate from any line used to handle materials, and shall be individually attended at all times while the employee wearing the lifeline is in the excavation.', null, null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(g)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '433fb5f3acb32cf57dc686f6d0dd19ff366669da3b3f53697d66f9e2244657ee', 26),
  (md5('academykb:section:cfr:1926.651(h)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(h)', '29 CFR 1926.651(h)', 'Specific excavation requirements: Protection from hazards associated with water accumulation', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(h) Protection from hazards associated with water accumulation. (1) Employees shall not work in excavations in which there is accumulated water, or in excavations in which water is accumulating, unless adequate precautions have been taken to protect employees against the hazards posed by water accumulation. The precautions necessary to protect employees adequately vary with each situation, but could include special support or shield systems to protect from cave-ins, water removal to control the level of accumulating water, or use of a safety harness and lifeline.
(2) If water is controlled or prevented from accumulating by the use of water removal equipment, the water removal equipment and operations shall be monitored by a competent person to ensure proper operation.
(3) If excavation work interrupts the natural drainage of surface water (such as streams), diversion ditches, dikes, or other suitable means shall be used to prevent surface water from entering the excavation and to provide adequate drainage of the area adjacent to the excavation. Excavations subject to runoff from heavy rains will require an inspection by a competent person and compliance with paragraphs (h)(1) and (h)(2) of this section.', null, null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(h)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'a2d7d897f598427b84dc987ee5949a71fd3dd052c2690b333c4d88e7ba495d0e', 27),
  (md5('academykb:section:cfr:1926.651(i)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(i)', '29 CFR 1926.651(i)', 'Specific excavation requirements: Stability of adjacent structures', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(i) Stability of adjacent structures. (1) Where the stability of adjoining buildings, walls, or other structures is endangered by excavation operations, support systems such as shoring, bracing, or underpinning shall be provided to ensure the stability of such structures for the protection of employees.
(2) Excavation below the level of the base or footing of any foundation or retaining wall that could be reasonably expected to pose a hazard to employees shall not be permitted except when:
(i) A support system, such as underpinning, is provided to ensure the safety of employees and the stability of the structure; or
(ii) The excavation is in stable rock; or
(iii) A registered professional engineer has approved the determination that the structure is sufficently removed from the excavation so as to be unaffected by the excavation activity; or
(iv) A registered professional engineer has approved the determination that such excavation work will not pose a hazard to employees.
(3) Sidewalks, pavements, and appurtenant structure shall not be undermined unless a support system or another method of protection is provided to protect employees from the possible collapse of such structures.', null, null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(i)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '8100f6203f4a504344475ad62d6bc80ee01dd8bd7eee7b8a9985e58726ebb68a', 28),
  (md5('academykb:section:cfr:1926.651(j)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(j)', '29 CFR 1926.651(j)', 'Specific excavation requirements: Protection of employees from loose rock or soil', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(j) Protection of employees from loose rock or soil. (1) Adequate protection shall be provided to protect employees from loose rock or soil that could pose a hazard by falling or rolling from an excavation face. Such protection shall consist of scaling to remove loose material; installation of protective barricades at intervals as necessary on the face to stop and contain falling material; or other means that provide equivalent protection.
(2) Employees shall be protected from excavated or other materials or equipment that could pose a hazard by falling or rolling into excavations. Protection shall be provided by placing and keeping such materials or equipment at least 2 feet (.61 m) from the edge of excavations, or by the use of retaining devices that are sufficient to prevent materials or equipment from falling or rolling into excavations, or by a combination of both if necessary.', null, null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(j)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'b699daef5633710a50ef3c047ce9ee39ae56e2d62258811f198700a9c1d676c7', 29),
  (md5('academykb:section:cfr:1926.651(k)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(k)', '29 CFR 1926.651(k)', 'Specific excavation requirements: Inspections', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(k) Inspections. (1) Daily inspections of excavations, the adjacent areas, and protective systems shall be made by a competent person for evidence of a situation that could result in possible cave-ins, indications of failure of protective systems, hazardous atmospheres, or other hazardous conditions. An inspection shall be conducted by the competent person prior to the start of work and as needed throughout the shift. Inspections shall also be made after every rainstorm or other hazard increasing occurrence. These inspections are only required when employee exposure can be reasonably anticipated.
(2) Where the competent person finds evidence of a situation that could result in a possible cave-in, indications of failure of protective systems, hazardous atmospheres, or other hazardous conditions, exposed employees shall be removed from the hazardous area until the necessary precautions have been taken to ensure their safety.', 'A competent person must inspect excavations, adjacent areas and protective systems daily before work starts and as needed, and after rainstorms or other hazard-increasing events.', null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(k)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '11f72db2f8061e934ed486542ce86e7f0ff932c2427e087b51b498e6cce9c040', 30),
  (md5('academykb:section:cfr:1926.651(l)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.651(l)', '29 CFR 1926.651(l)', 'Specific excavation requirements: paragraph (l)', '29 CFR Part 1926 › § 1926.651 Specific excavation requirements', 'requirement', 'full_text', '(l) Walkways shall be provided where employees or equipment are required or permitted to cross over excavations. Guardrails which comply with § 1926.502(b) shall be provided where walkways are 6 feet (1.8 m) or more above lower levels.', null, null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'landscaping', 'plumbing', 'pole-barns']::text[], array['excavation', 'trench', 'utilities', 'call before you dig', 'competent person', 'spoil pile']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.651#p-1926.651(l)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '88470353c3ca417b653bfed98f09dcfb6b8c71fabdef92d0707a9d747034fa6f', 31),
  (md5('academykb:section:cfr:1926.652(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.652(a)', '29 CFR 1926.652(a)', 'Requirements for protective systems: Protection of employees in excavations', '29 CFR Part 1926 › § 1926.652 Requirements for protective systems', 'requirement', 'full_text', '(a) Protection of employees in excavations. (1) Each employee in an excavation shall be protected from cave-ins by an adequate protective system designed in accordance with paragraph (b) or (c) of this section except when:
(i) Excavations are made entirely in stable rock; or
(ii) Excavations are less than 5 feet (1.52m) in depth and examination of the ground by a competent person provides no indication of a potential cave-in.
(2) Protective systems shall have the capacity to resist without failure all loads that are intended or could reasonably be expected to be applied or transmitted to the system.', 'Workers in an excavation must be protected from cave-ins by an adequate protective system unless the excavation is entirely in stable rock, or is less than 5 feet deep and a competent person finds no indication of a potential cave-in.', null, null, null, null, array['basements', 'concrete', 'excavation', 'foundations', 'general-contracting', 'plumbing']::text[], array['trench protection', 'shoring', 'sloping', 'trench box', 'excavation']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.652#p-1926.652(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'bdbdb3fd4b46e239ee4a5e41342da7f810e80c55ce13d5f5821e39a61599b520', 32),
  (md5('academykb:section:cfr:1926.850')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.850', '29 CFR 1926.850', 'Preparatory operations', '29 CFR Part 1926 › § 1926.850 Preparatory operations', 'requirement', 'full_text', '(a) Prior to permitting employees to start demolition operations, an engineering survey shall be made, by a competent person, of the structure to determine the condition of the framing, floors, and walls, and possibility of unplanned collapse of any portion of the structure. Any adjacent structure where employees may be exposed shall also be similarly checked. The employer shall have in writing evidence that such a survey has been performed.
(b) When employees are required to work within a structure to be demolished which has been damaged by fire, flood, explosion, or other cause, the walls or floor shall be shored or braced.
(c) All electric, gas, water, steam, sewer, and other service lines shall be shut off, capped, or otherwise controlled, outside the building line before demolition work is started. In each case, any utility company which is involved shall be notified in advance.
(d) If it is necessary to maintain any power, water or other utilities during demolition, such lines shall be temporarily relocated, as necessary, and protected.
(e) It shall also be determined if any type of hazardous chemicals, gases, explosives, flammable materials, or similarly dangerous substances have been used in any pipes, tanks, or other equipment on the property. When the presence of any such substances is apparent or suspected, testing and purging shall be performed and the hazard eliminated before demolition is started.
(f) Where a hazard exists from fragmentation of glass, such hazards shall be removed.
(g) Where a hazard exists to employees falling through wall openings, the opening shall be protected to a height of approximately 42 inches.
(h) When debris is dropped through holes in the floor without the use of chutes, the area onto which the material is dropped shall be completely enclosed with barricades not less than 42 inches high and not less than 6 feet back from the projected edge of the opening above. Signs, warning of the hazard of falling materials, shall be posted at each level. Removal shall not be permitted in this lower area until debris handling ceases above.
(i) All floor openings, not used as material drops, shall be covered over with material substantial enough to support the weight of any load which may be imposed. Such material shall be properly secured to prevent its accidental movement.
(j) Except for the cutting of holes in floors for chutes, holes through which to drop materials, preparation of storage space, and similar necessary preparatory work, the demolition of exterior walls and floor construction shall begin at the top of the structure and proceed downward. Each story of exterior wall and floor construction shall be removed and dropped into the storage space before commencing the removal of exterior walls and floors in the story next below.
(k) Employee entrances to multi-story structures being demolished shall be completely protected by sidewalk sheds or canopies, or both, providing protection from the face of the building for a minimum of 8 feet. All such canopies shall be at least 2 feet wider than the building entrances or openings (1 foot wider on each side thereof), and shall be capable of sustaining a load of 150 pounds per square foot.', null, null, null, null, null, array['commercial-remodeling', 'demolition', 'general-contracting', 'interior-remodeling']::text[], array['demolition', 'engineering survey', 'utilities shutoff']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.850', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'f2dcf760b285ad153ed367c2f6185ad9d5b751d53503bf991745362f9128fece', 33),
  (md5('academykb:section:cfr:1926.1052(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.1052(a)', '29 CFR 1926.1052(a)', 'Stairways: General', '29 CFR Part 1926 › § 1926.1052 Stairways', 'requirement', 'full_text', '(a) General. The following requirements apply to all stairways as indicated:
(1) Stairways that will not be a permanent part of the structure on which construction work is being performed shall have landings of not less than 30 inches (76 cm) in the direction of travel and extend at least 22 inches (56 cm) in width at every 12 feet (3.7 m) or less of vertical rise.
(2) Stairs shall be installed between 30° and 50° from horizontal.
(3) Riser height and tread depth shall be uniform within each flight of stairs, including any foundation structure used as one or more treads of the stairs. Variations in riser height or tread depth shall not be over 1/4 -inch (0.6 cm) in any stairway system.
(4) Where doors or gates open directly on a stairway, a platform shall be provided, and the swing of the door shall not reduce the effective width of the platform to less than 20 inches (51 cm).
(5) Metal pan landings and metal pan treads, when used, shall be secured in place before filling with concrete or other material.
(6) All parts of stairways shall be free of hazardous projections, such as protruding nails.
(7) Slippery conditions on stairways shall be eliminated before the stairways are used to reach other levels.', 'Construction stairways (the ones workers use during construction): landing size, a 30 to 50 degree slope, and riser heights and tread depths that are uniform within each flight, varying no more than 1/4 inch. These are worker-safety rules, not the building code rules for the finished home.', null, null, null, null, '{}'::text[], array['stairways', 'construction stairs', 'stair riser', 'stair tread', 'stair rail', 'handrail']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.1052#p-1926.1052(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '79e2e02782d578742bb014f82cdf3b4a0790f128eb0be4a4bded6a1eee2fe9fd', 34),
  (md5('academykb:section:cfr:1926.1052(b)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.1052(b)', '29 CFR 1926.1052(b)', 'Stairways: Temporary service', '29 CFR Part 1926 › § 1926.1052 Stairways', 'requirement', 'full_text', '(b) Temporary service. The following requirements apply to all stairways as indicated:
(1) Except during stairway construction, foot traffic is prohibited on stairways with pan stairs where the treads and/or landings are to be filled in with concrete or other material at a later date, unless the stairs are temporarily fitted with wood or other solid material at least to the top edge of each pan. Such temporary treads and landings shall be replaced when worn below the level of the top edge of the pan.
(2) Except during stairway construction, foot traffic is prohibited on skeleton metal stairs where permanent treads and/or landings are to be installed at a later date, unless the stairs are fitted with secured temporary treads and landings long enough to cover the entire tread and/or landing area.
(3) Treads for temporary service shall be made of wood or other solid material, and shall be installed the full width and depth of the stair.', null, null, null, null, null, '{}'::text[], array['stairways', 'construction stairs', 'stair riser', 'stair tread', 'stair rail', 'handrail']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.1052#p-1926.1052(b)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '3589699bb648b59a69bba730ab739569a3e5a954818804eabc3c899eee8d1255', 35),
  (md5('academykb:section:cfr:1926.1052(c)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.1052(c)', '29 CFR 1926.1052(c)', 'Stairways: Stairrails and handrails', '29 CFR Part 1926 › § 1926.1052 Stairways', 'requirement', 'full_text', '(c) Stairrails and handrails. The following requirements apply to all stairways as indicated:
(1) Stairways having four or more risers or rising more than 30 inches (76 cm), whichever is less, shall be equipped with:
(i) At least one handrail; and
(ii) One stairrail system along each unprotected side or edge.
When the top edge of a stairrail system also serves as a handrail, paragraph (c)(7) of this section applies.
(2) Winding and spiral stairways shall be equipped with a handrail offset sufficiently to prevent walking on those portions of the stairways where the tread width is less than 6 inches (15 cm).
(3) The height of stairrails shall be as follows:
(i) Stairrails installed after March 15, 1991, shall be not less than 36 inches (91.5 cm) from the upper surface of the stairrail system to the surface of the tread, in line with the face of the riser at the forward edge of the tread.
(ii) Stairrails installed before March 15, 1991, shall be not less than 30 inches (76 cm) nor more than 34 inches (86 cm) from the upper surface of the stairrail system to the surface of the tread, in line with the face of the riser at the forward edge of the tread.
(4) Midrails, screens, mesh, intermediate vertical members, or equivalent intermediate structural members, shall be provided between the top rail of the stairrail system and the stairway steps.
(i) Midrails, when used, shall be located at a height midway between the top edge of the stairrail system and the stairway steps.
(ii) Screens or mesh, when used, shall extend from the top rail to the stairway step, and along the entire opening between top rail supports.
(iii) When intermediate vertical members, such as balusters, are used between posts, they shall be not more than 19 inches (48 cm) apart.
(iv) Other structural members, when used, shall be installed such that there are no openings in the stairrail system that are more than 19 inches (48 cm) wide.
(5) Handrails and the top rails of stairrail systems shall be capable of withstanding, without failure, a force of at least 200 pounds (890 n) applied within 2 inches (5 cm) of the top edge, in any downward or outward direction, at any point along the top edge.
(6) The height of handrails shall be not more than 37 inches (94 cm) nor less than 30 inches (76 cm) from the upper surface of the handrail to the surface of the tread, in line with the face of the riser at the forward edge of the tread.
(7) When the top edge of a stairrail system also serves as a handrail, the height of the top edge shall be not more than 37 inches (94 cm) nor less than 36 inches (91.5 cm) from the upper surface of the stairrail system to the surface of the tread, in line with the face of the riser at the forward edge of the tread.
(8) Stairrail systems and handrails shall be so surfaced as to prevent injury to employees from punctures or lacerations, and to prevent snagging of clothing.
(9) Handrails shall provide an adequate handhold for employees grasping them to avoid falling.
(10) The ends of stairrail systems and handrails shall be constructed so as not to constitute a projection hazard.
(11) Handrails that will not be a permanent part of the structure being built shall have a minimum clearance of 3 inches (8 cm) between the handrail and walls, stairrail systems, and other objects.
(12) Unprotected sides and edges of stairway landings shall be provided with guardrail systems. Guardrail system criteria are contained in subpart M of this part.', 'Construction stairways with four or more risers or more than 30 inches of rise need at least one handrail and stairrails on unprotected sides, with height and strength requirements.', null, null, null, null, '{}'::text[], array['stairways', 'construction stairs', 'stair riser', 'stair tread', 'stair rail', 'handrail']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.1052#p-1926.1052(c)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '60398af4323d14b6f1afd91429140e0c0fbb6692bb2c36e6e79be0d08de5e64d', 36),
  (md5('academykb:section:cfr:1926.1053(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.1053(a)', '29 CFR 1926.1053(a)', 'Ladders: General', '29 CFR Part 1926 › § 1926.1053 Ladders', 'requirement', 'full_text', '(a) General. The following requirements apply to all ladders as indicated, including job-made ladders.
(1) Ladders shall be capable of supporting the following loads without failure:
(i) Each self-supporting portable ladder: At least four times the maximum intended load, except that each extra-heavy-duty type 1A metal or plastic ladder shall sustain at least 3.3 times the maximum intended load. The ability of a ladder to sustain the loads indicated in this paragraph shall be determined by applying or transmitting the requisite load to the ladder in a downward vertical direction. Ladders built and tested in conformance with the applicable provisions of appendix A of this subpart will be deemed to meet this requirement.
(ii) Each portable ladder that is not self-supporting: At least four times the maximum intended load, except that each extra-heavy-duty type 1A metal or plastic ladders shall sustain at least 3.3 times the maximum intended load. The ability of a ladder to sustain the loads indicated in this paragraph shall be determined by applying or transmitting the requisite load to the ladder in a downward vertical direction when the ladder is placed at an angle of 75 1/2 degrees from the horizontal. Ladders built and tested in conformance with the applicable provisions of appendix A will be deemed to meet this requirement.
(iii) Each fixed ladder: At least two loads of 250 pounds (114 kg) each, concentrated between any two consecutive attachments (the number and position of additional concentrated loads of 250 pounds (114 kg) each, determined from anticipated usage of the ladder, shall also be included), plus anticipated loads caused by ice buildup, winds, rigging, and impact loads resulting from the use of ladder safety devices. Each step or rung shall be capable of supporting a single concentrated load of at least 250 pounds (114 kg) applied in the middle of the step or rung. Ladders built in conformance with the applicable provisions of appendix A will be deemed to meet this requirement.
(2) Ladder rungs, cleats, and steps shall be parallel, level, and uniformly spaced when the ladder is in position for use.
(3)(i) Rungs, cleats, and steps of portable ladders (except as provided below) and fixed ladders (including individual-rung/step ladders) shall be spaced not less than 10 inches (25 cm) apart, nor more than 14 inches (36 cm) apart, as measured between center lines of the rungs, cleats, and steps.
(ii) Rungs, cleats, and steps of step stools shall be not less than 8 inches (20 cm) apart, nor more than 12 inches (31 cm) apart, as measured between center lines of the rungs, cleats, and steps.
(iii) Rungs, cleats, and steps of the base section of extension trestle ladders shall not be less than 8 inches (20 cm) nor more than 18 inches (46 cm) apart, as measured between center lines of the rungs, cleats, and steps. The rung spacing on the extension section of the extension trestle ladder shall be not less than 6 inches (15 cm) nor more than 12 inches (31 cm), as measured between center lines of the rungs, cleats, and steps.
(4)(i) The minimum clear distance between the sides of individual-rung/step ladders and the minimum clear distance between the side rails of other fixed ladders shall be 16 inches (41 cm).
(ii) The minimum clear distance between side rails for all portable ladders shall be 11 1/2 inches (29 cm).
(5) The rungs of individual-rung/step ladders shall be shaped such that employees'' feet cannot slide off the end of the rungs.
(6)(i) The rungs and steps of fixed metal ladders manufactured after March 15, 1991, shall be corrugated, knurled, dimpled, coated with skid-resistant material, or otherwise treated to minimize slipping.
(ii) The rungs and steps of portable metal ladders shall be corrugated, knurled, dimpled, coated with skid-resistant material, or otherwise treated to minimize slipping.
(7) Ladders shall not be tied or fastened together to provide longer sections unless they are specifically designed for such use.
(8) A metal spreader or locking device shall be provided on each stepladder to hold the front and back sections in an open position when the ladder is being used.
(9) When splicing is required to obtain a given length of side rail, the resulting side rail must be at least equivalent in strength to a one-piece side rail made of the same material.
(10) Except when portable ladders are used to gain access to fixed ladders (such as those on utility towers, billboards, and other structures where the bottom of the fixed ladder is elevated to limit access), when two or more separate ladders are used to reach an elevated work area, the ladders shall be offset with a platform or landing between the ladders. (The requirements to have guardrail systems with toeboards for falling object and overhead protection on platforms and landings are set forth in subpart M of this part.)
(11) Ladder components shall be surfaced so as to prevent injury to an employee from punctures or lacerations, and to prevent snagging of clothing.
(12) Wood ladders shall not be coated with any opaque covering, except for identification or warning labels which may be placed on one face only of a side rail.
(13) The minimum perpendicular clearance between fixed ladder rungs, cleats, and steps, and any obstruction behind the ladder shall be 7 inches (18 cm), except in the case of an elevator pit ladder, for which a minimum perpendicular clearance of 4 1/2 inches (11 cm) is required.
(14) The minimum perpendicular clearance between the center line of fixed ladder rungs, cleats, and steps, and any obstruction on the climbing side of the ladder shall be 30 inches (76 cm), except as provided in paragraph (a)(15) of this section.
(15) When unavoidable obstructions are encountered, the minimum perpendicular clearance between the centerline of fixed ladder rungs, cleats, and steps, and the obstruction on the climbing side of the ladder may be reduced to 24 inches (61 cm), provided that a deflection device is installed to guide employees around the obstruction.
(16) Through fixed ladders at their point of access/egress shall have a step-across distance of not less than 7 inches (18 cm) nor more than 12 inches (30 cm) as measured from the centerline of the steps or rungs to the nearest edge of the landing area. If the normal step-across distance exceeds 12 inches (30 cm), a landing platform shall be provided to reduce the distance to the specified limit.
(17) Fixed ladders without cages or wells shall have a clear width to the nearest permanent object of at least 15 inches (38 cm) on each side of the centerline of the ladder.
(18) Fixed ladders shall be provided with cages, wells, ladder safety devices, or self-retracting lifelines where the length of climb is less than 24 feet (7.3 m) but the top of the ladder is at a distance greater than 24 feet (7.3 m) above lower levels.
(19) Where the total length of a climb equals or exceeds 24 feet (7.3 m), fixed ladders shall be equipped with one of the following:
(i) Ladder safety devices; or
(ii) Self-retracting lifelines, and rest platforms at intervals not to exceed 150 feet (45.7 m); or
(iii) A cage or well, and multiple ladder sections, each ladder section not to exceed 50 feet (15.2 m) in length. Ladder sections shall be offset from adjacent sections, and landing platforms shall be provided at maximum intervals of 50 feet (15.2 m).
(20) Cages for fixed ladders shall conform to all of the following:
(i) Horizontal bands shall be fastened to the side rails of rail ladders, or directly to the structure, building, or equipment for individual-rung ladders;
(ii) Vertical bars shall be on the inside of the horizontal bands and shall be fastened to them;
(iii) Cages shall extend not less than 27 inches (68 cm), or more than 30 inches (76 cm) from the centerline of the step or rung (excluding the flare at the bottom of the cage), and shall not be less than 27 inches (68 cm) in width;
(iv) The inside of the cage shall be clear of projections;
(v) Horizontal bands shall be spaced not more than 4 feet (1.2 m) on center vertically;
(vi) Vertical bars shall be spaced at intervals not more than 9 1/2 inches (24 cm) on center horizontally;
(vii) The bottom of the cage shall be at a level not less than 7 feet (2.1 m) nor more than 8 feet (2.4 m) above the point of access to the bottom of the ladder. The bottom of the cage shall be flared not less than 4 inches (10 cm) all around within the distance between the bottom horizontal band and the next higher band;
(viii) The top of the cage shall be a minimum of 42 inches (1.1 m) above the top of the platform, or the point of access at the top of the ladder, with provision for access to the platform or other point of access.
(21) Wells for fixed ladders shall conform to all of the following:
(i) They shall completely encircle the ladder;
(ii) They shall be free of projections;
(iii) Their inside face on the climbing side of the ladder shall extend not less than 27 inches (68 cm) nor more than 30 inches (76 cm) from the centerline of the step or rung;
(iv) The inside clear width shall be at least 30 inches (76 cm);
(v) The bottom of the wall on the access side shall start at a level not less than 7 feet (2.1 m) nor more than 8 feet (2.4 m) above the point of access to the bottom of the ladder.
(22) Ladder safety devices, and related support systems, for fixed ladders shall conform to all of the following:
(i) They shall be capable of withstanding without failure a drop test consisting of an 18-inch (41 cm) drop of a 500-pound (226 kg) weight;
(ii) They shall permit the employee using the device to ascend or descend without continually having to hold, push or pull any part of the device, leaving both hands free for climbing;
(iii) They shall be activated within 2 feet (.61 m) after a fall occurs, and limit the descending velocity of an employee to 7 feet/sec. (2.1 m/sec.) or less;
(iv) The connection between the carrier or lifeline and the point of attachment to the body belt or harness shall not exceed 9 inches (23 cm) in length.
(23) The mounting of ladder safety devices for fixed ladders shall conform to the following:
(i) Mountings for rigid carriers shall be attached at each end of the carrier, with intermediate mountings, as necessary, spaced along the entire length of the carrier, to provide the strength necessary to stop employees'' falls.
(ii) Mountings for flexible carriers shall be attached at each end of the carrier. When the system is exposed to wind, cable guides for flexible carriers shall be installed at a minimum spacing of 25 feet (7.6 m) and maximum spacing of 40 feet (12.2 m) along the entire length of the carrier, to prevent wind damage to the system.
(iii) The design and installation of mountings and cable guides shall not reduce the design strength of the ladder.
(24) The side rails of through or side-step fixed ladders shall extend 42 inches (1.1 m) above the top of the access level or landing platform served by the ladder. For a parapet ladder, the access level shall be the roof if the parapet is cut to permit passage through the parapet; if the parapet is continuous, the access level shall be the top of the parapet.
(25) For through-fixed-ladder extensions, the steps or rungs shall be omitted from the extension and the extension of the side rails shall be flared to provide not less than 24 inches (61 cm) nor more than 30 inches (76 cm) clearance between side rails. Where ladder safety devices are provided, the maximum clearance between side rails of the extensions shall not exceed 36 inches (91 cm).
(26) For side-step fixed ladders, the side rails and the steps or rungs shall be continuous in the extension.
(27) Individual-rung/step ladders, except those used where their access openings are covered with manhole covers or hatches, shall extend at least 42 inches (1.1 m) above an access level or landing platform either by the continuation of the rung spacings as horizontal grab bars or by providing vertical grab bars that shall have the same lateral spacing as the vertical legs of the rungs.', 'Ladder construction: load capacities, rung spacing and other design requirements for portable, fixed and job-made ladders.', null, null, null, null, '{}'::text[], array['ladders', 'ladder', 'extension ladder', 'ladder angle', 'ladder side rails']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.1053#p-1926.1053(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '959d2dd08b973cd3ef67453e0d5a69cfe2d38c807e3ddaef789968f38648df88', 37),
  (md5('academykb:section:cfr:1926.1053(b)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.1053(b)', '29 CFR 1926.1053(b)', 'Ladders: Use', '29 CFR Part 1926 › § 1926.1053 Ladders', 'requirement', 'full_text', '(b) Use. The following requirements apply to the use of all ladders, including job-made ladders, except as otherwise indicated:
(1) When portable ladders are used for access to an upper landing surface, the ladder side rails shall extend at least 3 feet (.9 m) above the upper landing surface to which the ladder is used to gain access; or, when such an extension is not possible because of the ladder''s length, then the ladder shall be secured at its top to a rigid support that will not deflect, and a grasping device, such as a grabrail, shall be provided to assist employees in mounting and dismounting the ladder. In no case shall the extension be such that ladder deflection under a load would, by itself, cause the ladder to slip off its support.
(2) Ladders shall be maintained free of oil, grease, and other slipping hazards.
(3) Ladders shall not be loaded beyond the maximum intended load for which they were built, nor beyond their manufacturer''s rated capacity.
(4) Ladders shall be used only for the purpose for which they were designed.
(5)(i) Non-self-supporting ladders shall be used at an angle such that the horizontal distance from the top support to the foot of the ladder is approximately one-quarter of the working length of the ladder (the distance along the ladder between the foot and the top support).
(ii) Wood job-made ladders with spliced side rails shall be used at an angle such that the horizontal distance is one-eighth the working length of the ladder.
(iii) Fixed ladders shall be used at a pitch no greater than 90 degrees from the horizontal, as measured to the back side of the ladder.
(6) Ladders shall be used only on stable and level surfaces unless secured to prevent accidental displacement.
(7) Ladders shall not be used on slippery surfaces unless secured or provided with slip-resistant feet to prevent accidental displacement. Slip-resistant feet shall not be used as a substitute for care in placing, lashing, or holding a ladder that is used upon slippery surfaces including, but not limited to, flat metal or concrete surfaces that are constructed so they cannot be prevented from becoming slippery.
(8) Ladders placed in any location where they can be displaced by workplace activities or traffic, such as in passageways, doorways, or driveways, shall be secured to prevent accidental displacement, or a barricade shall be used to keep the activities or traffic away from the ladder.
(9) The area around the top and bottom of ladders shall be kept clear.
(10) The top of a non-self-supporting ladder shall be placed with the two rails supported equally unless it is equipped with a single support attachment.
(11) Ladders shall not be moved, shifted, or extended while occupied.
(12) Ladders shall have nonconductive siderails if they are used where the employee or the ladder could contact exposed energized electrical equipment, except as provided in § 1926.955(b) and (c) of this part.
(13) The top or top step of a stepladder shall not be used as a step.
(14) Cross-bracing on the rear section of stepladders shall not be used for climbing unless the ladders are designed and provided with steps for climbing on both front and rear sections.
(15) Ladders shall be inspected by a competent person for visible defects on a periodic basis and after any occurrence that could affect their safe use.
(16) Portable ladders with structural defects, such as, but not limited to, broken or missing rungs, cleats, or steps, broken or split rails, corroded components, or other faulty or defective components, shall either be immediately marked in a manner that readily identifies them as defective, or be tagged with “Do Not Use” or similar language, and shall be withdrawn from service until repaired.
(17) Fixed ladders with structural defects, such as, but not limited to, broken or missing rungs, cleats, or steps, broken or split rails, or corroded components, shall be withdrawn from service until repaired. The requirement to withdraw a defective ladder from service is satisfied if the ladder is either:
(i) Immediately tagged with “Do Not Use” or similar language,
(ii) Marked in a manner that readily identifies it as defective;
(iii) Or blocked (such as with a plywood attachment that spans several rungs).
(18) Ladder repairs shall restore the ladder to a condition meeting its original design criteria, before the ladder is returned to use.
(19) Single-rail ladders shall not be used.
(20) When ascending or descending a ladder, the user shall face the ladder.
(21) Each employee shall use at least one hand to grasp the ladder when progressing up and/or down the ladder.
(22) An employee shall not carry any object or load that could cause the employee to lose balance and fall.', 'Ladder use: when a portable ladder is used to reach an upper landing, its side rails must extend at least 3 feet above the landing, or the ladder must be secured at the top with a grab device. Other rules cover loads, angles, footing and inspection.', null, null, null, null, '{}'::text[], array['ladders', 'ladder', 'extension ladder', 'ladder angle', 'ladder side rails']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.1053#p-1926.1053(b)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '3de99560061ee4dde9317f90db4e865fe5b7070db57261b5a3658a8f571ea6be', 38),
  (md5('academykb:section:cfr:1926.1060')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.1060', '29 CFR 1926.1060', 'Training requirements', '29 CFR Part 1926 › § 1926.1060 Training requirements', 'requirement', 'full_text', 'The following training provisions clarify the requirements of § 1926.21(b)(2), regarding the hazards addressed in subpart X.
(a) The employer shall provide a training program for each employee using ladders and stairways, as necessary. The program shall enable each employee to recognize hazards related to ladders and stairways, and shall train each employee in the procedures to be followed to minimize these hazards.
(1) The employer shall ensure that each employee has been trained by a competent person in the following areas, as applicable:
(i) The nature of fall hazards in the work area;
(ii) The correct procedures for erecting, maintaining, and disassembling the fall protection systems to be used;
(iii) The proper construction, use, placement, and care in handling of all stairways and ladders;
(iv) The maximum intended load-carrying capacities of ladders used; and
(v) The standards contained in this subpart.
(b) Retraining shall be provided for each employee as necessary so that the employee maintains the understanding and knowledge acquired through compliance with this section.', null, null, null, null, null, '{}'::text[], array['ladder training', 'stairway training', 'training']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.1060', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '367cdceb62ba2f21a26f24725539bb6540a8d9faafd61d4abfaadb847d94f551', 39),
  (md5('academykb:section:cfr:1926.62(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.62(a)', '29 CFR 1926.62(a)', 'Lead: Scope', '29 CFR Part 1926 › § 1926.62 Lead', 'requirement', 'full_text', '(a) Scope. This section applies to all construction work where an employee may be occupationally exposed to lead. All construction work excluded from coverage in the general industry standard for lead by 29 CFR 1910.1025(a)(2) is covered by this standard. Construction work is defined as work for construction, alteration and/or repair, including painting and decorating. It includes but is not limited to the following:
(1) Demolition or salvage of structures where lead or materials containing lead are present;
(2) Removal or encapsulation of materials containing lead;
(3) New construction, alteration, repair, or renovation of structures, substrates, or portions thereof, that contain lead, or materials containing lead;
(4) Installation of products containing lead;
(5) Lead contamination/emergency cleanup;
(6) Transportation, disposal, storage, or containment of lead or materials containing lead on the site or location at which construction activities are performed, and
(7) Maintenance operations associated with the construction activities described in this paragraph.', 'The OSHA lead standard applies to all construction work where workers may be exposed to lead, including demolition, removal, renovation and painting work on lead-containing materials.', null, null, null, null, array['demolition', 'exterior-remodeling', 'general-contracting', 'interior-remodeling', 'painting', 'windows-doors']::text[], array['lead', 'lead exposure']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.62#p-1926.62(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '07f82c9b617b8c42ebccbcf219bfb2475349c4b0aedaba984f1d332a482074f0', 40),
  (md5('academykb:section:cfr:1926.1101(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.1101(a)', '29 CFR 1926.1101(a)', 'Asbestos: Scope and application', '29 CFR Part 1926 › § 1926.1101 Asbestos', 'requirement', 'full_text', '(a) Scope and application. This section regulates asbestos exposure in all work as defined in 29 CFR 1910.12(b), including but not limited to the following:
(1) Demolition or salvage of structures where asbestos is present;
(2) Removal or encapsulation of materials containing asbestos;
(3) Construction, alteration, repair, maintenance, or renovation of structures, substrates, or portions thereof, that contain asbestos;
(4) Installation of products containing asbestos;
(5) Asbestos spill/emergency cleanup; and
(6) Transportation, disposal, storage, containment of and housekeeping activities involving asbestos or products containing asbestos, on the site or location at which construction activities are performed.
(7) Coverage under this standard shall be based on the nature of the work operation involving asbestos exposure.
(8) This section does not apply to asbestos-containing asphalt roof coatings, cements and mastics.', 'The OSHA asbestos standard applies to construction work involving asbestos, including demolition, removal, renovation and repair of materials that contain asbestos.', null, null, null, null, array['demolition', 'flooring', 'general-contracting', 'insulation', 'interior-remodeling', 'roofing']::text[], array['asbestos']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.1101#p-1926.1101(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '598a5cd7adb8c27ccda74bc628c02914cfcdb649f0bf7aa30077bc67cbc77400', 41),
  (md5('academykb:section:cfr:1926.1153(a)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.1153(a)', '29 CFR 1926.1153(a)', 'Respirable crystalline silica: Scope and application', '29 CFR Part 1926 › § 1926.1153 Respirable crystalline silica', 'requirement', 'full_text', '(a) Scope and application. This section applies to all occupational exposures to respirable crystalline silica in construction work, except where employee exposure will remain below 25 micrograms per cubic meter of air (25 µg/m 3) as an 8-hour time-weighted average (TWA) under any foreseeable conditions.', 'The silica standard applies to all occupational exposures to respirable crystalline silica in construction work, except where exposure will stay below 25 micrograms per cubic meter as an 8-hour time-weighted average under any foreseeable conditions.', null, null, null, null, array['asphalt-paving', 'cabinets-countertops', 'concrete', 'demolition', 'foundations', 'general-contracting', 'masonry', 'tile']::text[], array['silica', 'concrete cutting', 'dust control', 'respirator']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.1153#p-1926.1153(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'c6d4e23d5f9cbb5cd7d69915671554c85d4bec183f72446da41c7556bddf26c6', 42),
  (md5('academykb:section:cfr:1926.1153(c)')::uuid, md5('academykb:source:osha-1926')::uuid, '1926.1153(c)', '29 CFR 1926.1153(c)', 'Respirable crystalline silica: Specified exposure control methods', '29 CFR Part 1926 › § 1926.1153 Respirable crystalline silica', 'requirement', 'full_text', '(c) Specified exposure control methods. (1) For each employee engaged in a task identified on Table 1, the employer shall fully and properly implement the engineering controls, work practices, and respiratory protection specified for the task on Table 1, unless the employer assesses and limits the exposure of the employee to respirable crystalline silica in accordance with paragraph (d) of this section.
Table 1—Specified Exposure Control Methods When Working With Materials Containing Crystalline Silica
(2) When implementing the control measures specified in Table 1, each employer shall:
(i) For tasks performed indoors or in enclosed areas, provide a means of exhaust as needed to minimize the accumulation of visible airborne dust;
(ii) For tasks performed using wet methods, apply water at flow rates sufficient to minimize release of visible dust;
(iii) For measures implemented that include an enclosed cab or booth, ensure that the enclosed cab or booth:
(A) Is maintained as free as practicable from settled dust;
(B) Has door seals and closing mechanisms that work properly;
(C) Has gaskets and seals that are in good condition and working properly;
(D) Is under positive pressure maintained through continuous delivery of fresh air;
(E) Has intake air that is filtered through a filter that is 95% efficient in the 0.3-10.0 µm range (e.g., MERV-16 or better); and
(F) Has heating and cooling capabilities.
(3) Where an employee performs more than one task on Table 1 during the course of a shift, and the total duration of all tasks combined is more than four hours, the required respiratory protection for each task is the respiratory protection specified for more than four hours per shift. If the total duration of all tasks on Table 1 combined is less than four hours, the required respiratory protection for each task is the respiratory protection specified for less than four hours per shift.', 'Employers can comply by fully following the engineering controls, work practices and respirator rules listed for each task in Table 1 (for example, water delivery or vacuum dust collection on saws and grinders).', null, null, null, null, array['asphalt-paving', 'cabinets-countertops', 'concrete', 'demolition', 'foundations', 'general-contracting', 'masonry', 'tile']::text[], array['silica', 'concrete cutting', 'dust control', 'respirator']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1926.1153#p-1926.1153(c)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '2b325a36c25bf58795f32ce1729ccd91c68f8c866dd27f58064b4aa24c00454d', 43),
  (md5('academykb:section:cfr:1904.1')::uuid, md5('academykb:source:osha-1904')::uuid, '1904.1', '29 CFR 1904.1', 'Partial exemption for employers with 10 or fewer employees', '29 CFR Part 1904 › § 1904.1 Partial exemption for employers with 10 or fewer employees', 'requirement', 'full_text', '(a) Basic requirement. (1) If your company had 10 or fewer employees at all times during the last calendar year, you do not need to keep OSHA injury and illness records unless OSHA or the Bureau of Labor Statistics informs you in writing that you must keep records under § 1904.41 or § 1904.42. However, as required by § 1904.39, all employers covered by the OSH Act must report to OSHA any work-related incident that results in a fatality, the in-patient hospitalization of one or more employees, an employee amputation, or an employee loss of an eye.
(2) If your company had more than ten (10) employees at any time during the last calendar year, you must keep OSHA injury and illness records unless your establishment is classified as a partially exempt industry under § 1904.2.
(b) Implementation—(1) Is the partial exemption for size based on the size of my entire company or on the size of an individual business establishment? The partial exemption for size is based on the number of employees in the entire company.
(2) How do I determine the size of my company to find out if I qualify for the partial exemption for size? To determine if you are exempt because of size, you need to determine your company''s peak employment during the last calendar year. If you had no more than 10 employees at any time in the last calendar year, your company qualifies for the partial exemption for size.', 'Companies with 10 or fewer employees at all times during the last calendar year generally don''t need to keep OSHA injury and illness records unless told to in writing, but every covered employer must still report serious incidents under 1904.39.', null, null, null, null, '{}'::text[], array['recordkeeping', 'osha 300 log', 'small employer']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1904.1', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'bcc916339fd7df99983f6df847697a5c9d152a7eee6d70d61c3d69858bf0cb6c', 44),
  (md5('academykb:section:cfr:1904.39(a)')::uuid, md5('academykb:source:osha-1904')::uuid, '1904.39(a)', '29 CFR 1904.39(a)', 'Reporting fatalities, hospitalizations, amputations, and losses of an eye as a result of work-related incidents to OSHA: Basic requirement', '29 CFR Part 1904 › § 1904.39 Reporting fatalities, hospitalizations, amputations, and losses of an eye as a result of work-related incidents to OSHA', 'requirement', 'full_text', '(a) Basic requirement. (1) Within eight (8) hours after the death of any employee as a result of a work-related incident, you must report the fatality to the Occupational Safety and Health Administration (OSHA), U.S. Department of Labor.
(2) Within twenty-four (24) hours after the in-patient hospitalization of one or more employees or an employee''s amputation or an employee''s loss of an eye, as a result of a work-related incident, you must report the in-patient hospitalization, amputation, or loss of an eye to OSHA.
(3) You must report the fatality, in-patient hospitalization, amputation, or loss of an eye using one of the following methods:
(i) By telephone or in person to the OSHA Area Office that is nearest to the site of the incident.
(ii) By telephone to the OSHA toll-free central telephone number, 1-800-321-OSHA (1-800-321-6742).
(iii) By electronic submission using the reporting application located on OSHA''s public Web site at www.osha.gov.', 'Report a work-related fatality to OSHA within 8 hours, and an in-patient hospitalization, amputation or loss of an eye within 24 hours.', null, null, null, null, '{}'::text[], array['reporting', 'fatality', 'injury reporting']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1904.39#p-1904.39(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '468e3a393f8a9d2ca6d2b6f771280ddf01c42a5c1a6653e674e49f510f9c1ce4', 45),
  (md5('academykb:section:cfr:745.82')::uuid, md5('academykb:source:epa-745')::uuid, '745.82', '40 CFR 745.82', 'Applicability', '40 CFR Part 745 › § 745.82 Applicability', 'requirement', 'full_text', '(a) This subpart applies to all renovations performed for compensation in target housing and child-occupied facilities, except for the following:
(1) Renovations in target housing or child-occupied facilities in which a written determination has been made by an inspector or risk assessor (certified pursuant to either Federal regulations at § 745.226 or a State or Tribal certification program authorized pursuant to § 745.324) that the components affected by the renovation are free of paint or other surface coatings that contain lead equal to or in excess of 1.0 milligrams/per square centimeter (mg/cm 2) or 0.5% by weight, where the firm performing the renovation has obtained a copy of the determination.
(2) Renovations in target housing or child-occupied facilities in which a certified renovator, using an EPA recognized test kit as defined in § 745.83 and following the kit manufacturer''s instructions, has tested each component affected by the renovation and determined that the components are free of paint or other surface coatings that contain lead equal to or in excess of 1.0 mg/cm 2 or 0.5% by weight. If the components make up an integrated whole, such as the individual stair treads and risers of a single staircase, the renovator is required to test only one of the individual components, unless the individual components appear to have been repainted or refinished separately.
(3) Renovations in target housing or child-occupied facilities in which a certified renovator has collected a paint chip sample from each painted component affected by the renovation and a laboratory recognized by EPA pursuant to section 405(b) of TSCA as being capable of performing analyses for lead compounds in paint chip samples has determined that the samples are free of paint or other surface coatings that contain lead equal to or in excess of 1.0 mg/cm 2 or 0.5% by weight. If the components make up an integrated whole, such as the individual stair treads and risers of a single staircase, the renovator is required to test only one of the individual components, unless the individual components appear to have been repainted or refinished separately.
(b) The information distribution requirements in § 745.84 do not apply to emergency renovations, which are renovation activities that were not planned but result from a sudden, unexpected event (such as non-routine failures of equipment) that, if not immediately attended to, presents a safety or public health hazard, or threatens equipment and/or property with significant damage. Interim controls performed in response to an elevated blood lead level in a resident child are also emergency renovations. Emergency renovations other than interim controls are also exempt from the warning sign, containment, waste handling, training, and certification requirements in §§ 745.85, 745.89, and 745.90 to the extent necessary to respond to the emergency. Emergency renovations are not exempt from the cleaning requirements of § 745.85(a)(5), which must be performed by certified renovators or individuals trained in accordance with § 745.90(b)(2), the cleaning verification requirements of § 745.85(b), which must be performed by certified renovators, and the recordkeeping requirements of § 745.86(b)(6) and (b)(7).', 'The federal RRP rule applies to renovations for compensation in target housing and child-occupied facilities, except where the affected components were found free of lead-based paint by a certified inspector or risk assessor, by a certified renovator using an EPA-recognized test kit, or by an EPA-recognized lab testing paint chips (other listed exceptions apply).', null, null, null, null, array['bathrooms', 'exterior-remodeling', 'general-contracting', 'handyman', 'interior-remodeling', 'kitchens', 'painting', 'siding', 'windows-doors']::text[], array['lead paint', 'rrp', 'pre-1978', 'renovation']::text[], null, 'https://www.ecfr.gov/current/title-40/section-745.82', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '84b5cc33b9d91b58e24947c90202c3a26f192e946fab93c5175726c2a09f4363', 46),
  (md5('academykb:section:cfr:745.84(a)')::uuid, md5('academykb:source:epa-745')::uuid, '745.84(a)', '40 CFR 745.84(a)', 'Information distribution requirements: Renovations in dwelling units', '40 CFR Part 745 › § 745.84 Information distribution requirements', 'requirement', 'full_text', '(a) Renovations in dwelling units. No more than 60 days before beginning renovation activities in any residential dwelling unit of target housing, the firm performing the renovation must:
(1) Provide the owner of the unit with the pamphlet, and comply with one of the following:
(i) Obtain, from the owner, a written acknowledgment that the owner has received the pamphlet.
(ii) Obtain a certificate of mailing at least 7 days prior to the renovation.
(2) In addition to the requirements in paragraph (a)(1) of this section, if the owner does not occupy the dwelling unit, provide an adult occupant of the unit with the pamphlet, and comply with one of the following:
(i) Obtain, from the adult occupant, a written acknowledgment that the occupant has received the pamphlet; or certify in writing that a pamphlet has been delivered to the dwelling and that the firm performing the renovation has been unsuccessful in obtaining a written acknowledgment from an adult occupant. Such certification must include the address of the unit undergoing renovation, the date and method of delivery of the pamphlet, names of the persons delivering the pamphlet, reason for lack of acknowledgment (e.g., occupant refuses to sign, no adult occupant available), the signature of a representative of the firm performing the renovation, and the date of signature.
(ii) Obtain a certificate of mailing at least 7 days prior to the renovation.', 'No more than 60 days before renovating a dwelling unit in target housing, the firm must give the owner EPA''s lead pamphlet and keep proof (acknowledgment or mailing certificate).', null, null, null, null, array['exterior-remodeling', 'general-contracting', 'handyman', 'interior-remodeling', 'painting', 'siding', 'windows-doors']::text[], array['lead paint', 'renovate right', 'pre-renovation education', 'rrp']::text[], null, 'https://www.ecfr.gov/current/title-40/section-745.84#p-745.84(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '3d7b581fd611712cac6deb0bfbaf27dc09b3d443ff3fa881ba11e2102ecb6d62', 47),
  (md5('academykb:section:cfr:745.85(a)')::uuid, md5('academykb:source:epa-745')::uuid, '745.85(a)', '40 CFR 745.85(a)', 'Work practice standards: Standards for renovation activities', '40 CFR Part 745 › § 745.85 Work practice standards', 'requirement', 'full_text', '(a) Standards for renovation activities. Renovations must be performed by certified firms using certified renovators as directed in § 745.89. The responsibilities of certified firms are set forth in § 745.89(d) and the responsibilities of certified renovators are set forth in § 745.90(b).
(1) Occupant protection. Firms must post signs clearly defining the work area and warning occupants and other persons not involved in renovation activities to remain outside of the work area. To the extent practicable, these signs must be in the primary language of the occupants. These signs must be posted before beginning the renovation and must remain in place and readable until the renovation and the post-renovation cleaning verification have been completed. If warning signs have been posted in accordance with 24 CFR 35.1345(b)(2) or 29 CFR 1926.62(m), additional signs are not required by this section.
(2) Containing the work area. Before beginning the renovation, the firm must isolate the work area so that no dust or debris leaves the work area while the renovation is being performed. In addition, the firm must maintain the integrity of the containment by ensuring that any plastic or other impermeable materials are not torn or displaced, and taking any other steps necessary to ensure that no dust or debris leaves the work area while the renovation is being performed. The firm must also ensure that containment is installed in such a manner that it does not interfere with occupant and worker egress in an emergency.
(i) Interior renovations. The firm must:
(A) Remove all objects from the work area, including furniture, rugs, and window coverings, or cover them with plastic sheeting or other impermeable material with all seams and edges taped or otherwise sealed.
(B) Close and cover all ducts opening in the work area with taped-down plastic sheeting or other impermeable material.
(C) Close windows and doors in the work area. Doors must be covered with plastic sheeting or other impermeable material. Doors used as an entrance to the work area must be covered with plastic sheeting or other impermeable material in a manner that allows workers to pass through while confining dust and debris to the work area.
(D) Cover the floor surface, including installed carpet, with taped-down plastic sheeting or other impermeable material in the work area 6 feet beyond the perimeter of surfaces undergoing renovation or a sufficient distance to contain the dust, whichever is greater. Floor containment measures may stop at the edge of the vertical barrier when using a vertical containment system consisting of impermeable barriers that extend from the floor to the ceiling and are tightly sealed at joints with the floor, ceiling and walls.
(E) Use precautions to ensure that all personnel, tools, and other items, including the exteriors of containers of waste, are free of dust and debris before leaving the work area.
(ii) Exterior renovations. The firm must:
(A) Close all doors and windows within 20 feet of the renovation. On multi-story buildings, close all doors and windows within 20 feet of the renovation on the same floor as the renovation, and close all doors and windows on all floors below that are the same horizontal distance from the renovation.
(B) Ensure that doors within the work area that will be used while the job is being performed are covered with plastic sheeting or other impermeable material in a manner that allows workers to pass through while confining dust and debris to the work area.
(C) Cover the ground with plastic sheeting or other disposable impermeable material extending 10 feet beyond the perimeter of surfaces undergoing renovation or a sufficient distance to collect falling paint debris, whichever is greater, unless the property line prevents 10 feet of such ground covering. Ground containment measures may stop at the edge of the vertical barrier when using a vertical containment system.
(D) If the renovation will affect surfaces within 10 feet of the property line, the renovation firm must erect vertical containment or equivalent extra precautions in containing the work area to ensure that dust and debris from the renovation does not contaminate adjacent buildings or migrate to adjacent properties. Vertical containment or equivalent extra precautions in containing the work area may also be necessary in other situations in order to prevent contamination of other buildings, other areas of the property, or adjacent buildings or properties.
(3) Prohibited and restricted practices. The work practices listed below are prohibited or restricted during a renovation as follows:
(i) Open-flame burning or torching of painted surfaces is prohibited.
(ii) The use of machines designed to remove paint or other surface coatings through high speed operation such as sanding, grinding, power planing, needle gun, abrasive blasting, or sandblasting, is prohibited on painted surfaces unless such machines have shrouds or containment systems and are equipped with a HEPA vacuum attachment to collect dust and debris at the point of generation. Machines must be operated so that no visible dust or release of air occurs outside the shroud or containment system.
(iii) Operating a heat gun on painted surfaces is permitted only at temperatures below 1,100 degrees Fahrenheit.
(4) Waste from renovations. (i) Waste from renovation activities must be contained to prevent releases of dust and debris before the waste is removed from the work area for storage or disposal. If a chute is used to remove waste from the work area, it must be covered.
(ii) At the conclusion of each work day and at the conclusion of the renovation, waste that has been collected from renovation activities must be stored under containment, in an enclosure, or behind a barrier that prevents release of dust and debris out of the work area and prevents access to dust and debris.
(iii) When the firm transports waste from renovation activities, the firm must contain the waste to prevent release of dust and debris.
(5) Cleaning the work area. After the renovation has been completed, the firm must clean the work area until no dust, debris or residue remains.
(i) Interior and exterior renovations. The firm must:
(A) Collect all paint chips and debris and, without dispersing any of it, seal this material in a heavy-duty bag.
(B) Remove the protective sheeting. Mist the sheeting before folding it, fold the dirty side inward, and either tape shut to seal or seal in heavy-duty bags. Sheeting used to isolate contaminated rooms from non-contaminated rooms must remain in place until after the cleaning and removal of other sheeting. Dispose of the sheeting as waste.
(ii) Additional cleaning for interior renovations. The firm must clean all objects and surfaces in the work area and within 2 feet of the work area in the following manner, cleaning from higher to lower:
(A) Walls. Clean walls starting at the ceiling and working down to the floor by either vacuuming with a HEPA vacuum or wiping with a damp cloth.
(B) Remaining surfaces. Thoroughly vacuum all remaining surfaces and objects in the work area, including furniture and fixtures, with a HEPA vacuum. The HEPA vacuum must be equipped with a beater bar when vacuuming carpets and rugs.
(C) Wipe all remaining surfaces and objects in the work area, except for carpeted or upholstered surfaces, with a damp cloth. Mop uncarpeted floors thoroughly, using a mopping method that keeps the wash water separate from the rinse water, such as the 2-bucket mopping method, or using a wet mopping system.', 'Covered renovations must be done by certified firms using certified renovators, with warning signs, containment, restricted practices and cleaning as listed.', null, null, null, null, array['exterior-remodeling', 'general-contracting', 'handyman', 'interior-remodeling', 'painting', 'siding', 'windows-doors']::text[], array['lead paint', 'lead-safe work practices', 'containment', 'rrp']::text[], null, 'https://www.ecfr.gov/current/title-40/section-745.85#p-745.85(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '1699d8f739bc1e20ea0463aea2079c1fe1f7f734927bdcbcda9505bfc5c1c7da', 48),
  (md5('academykb:section:cfr:745.89(a)')::uuid, md5('academykb:source:epa-745')::uuid, '745.89(a)', '40 CFR 745.89(a)', 'Firm certification: Initial certification', '40 CFR Part 745 › § 745.89 Firm certification', 'requirement', 'full_text', '(a) Initial certification. (1) Firms that perform renovations for compensation must electronically apply to EPA for certification to perform renovations or dust sampling. To apply, a firm must submit to EPA a completed “Application for Firms,” signed by an authorized agent of the firm, and pay electronically at least the correct amount of fees. If a firm pays more than the correct amount of fees, EPA will reimburse the firm for the excess amount.
(2) After EPA receives a firm''s application, EPA will take one of the following actions within 90 days of the date the application is received:
(i) EPA will approve a firm''s application if EPA determines that it is complete and that the environmental compliance history of the firm, its principals, or its key employees does not show an unwillingness or inability to maintain compliance with environmental statutes or regulations. An application is complete if it contains all of the information requested on the form and includes at least the correct amount of fees. When EPA approves a firm''s application, EPA will issue the firm a certificate with an expiration date not more than 5 years from the date the application is approved. EPA certification allows the firm to perform renovations covered by this section in any State or Indian Tribal area that does not have a renovation program that is authorized under subpart Q of this part.
(ii) EPA will request a firm to supplement its application if EPA determines that the application is incomplete. If EPA requests a firm to supplement its application, the firm must submit the requested information or pay the additional fees within 30 days of the date of the request.
(iii) EPA will not approve a firm''s application if the firm does not supplement its application in accordance with paragraph (a)(2)(ii) of this section or if EPA determines that the environmental compliance history of the firm, its principals, or its key employees demonstrates an unwillingness or inability to maintain compliance with environmental statutes or regulations. EPA will send the firm a letter giving the reason for not approving the application. EPA will not refund the application fees. A firm may reapply for certification at any time by filing a new, complete application that includes the correct amount of fees.', 'Firms that perform renovations for compensation must apply electronically to EPA for firm certification and pay the fee.', null, null, null, null, array['exterior-remodeling', 'general-contracting', 'handyman', 'interior-remodeling', 'painting', 'siding', 'windows-doors']::text[], array['lead firm certification', 'rrp certification', 'lead paint']::text[], null, 'https://www.ecfr.gov/current/title-40/section-745.89#p-745.89(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '549284f4dc6d0160fea05aedc83ea151bb811bf0e5e70c9a327ee774b6edfb22', 49),
  (md5('academykb:section:cfr:391.11')::uuid, md5('academykb:source:fmcsa')::uuid, '391.11', '49 CFR 391.11', 'General qualifications of drivers', '49 CFR Part 391 › § 391.11 General qualifications of drivers', 'requirement', 'full_text', '(a) A person shall not drive a commercial motor vehicle unless he/she is qualified to drive a commercial motor vehicle. Except as provided in § 391.63, a motor carrier shall not require or permit a person to drive a commercial motor vehicle unless that person is qualified to drive a commercial motor vehicle.
(b) Except as provided in subpart G of this part, a person is qualified to drive a motor vehicle if he/she—
(1) Is at least 21 years old;
(2) Can read and speak the English language sufficiently to converse with the general public, to understand highway traffic signs and signals in the English language, to respond to official inquiries, and to make entries on reports and records;
(3) Can, by reason of experience, training, or both, safely operate the type of commercial motor vehicle he/she drives;
(4) Is physically qualified to drive a commercial motor vehicle in accordance with subpart E—Physical Qualifications and Examinations of this part;
(5) Has a currently valid commercial motor vehicle operator''s license issued only by one State or jurisdiction;
(6) Is not disqualified to drive a commercial motor vehicle under the rules in § 391.15; and
(7) Has successfully completed a driver''s road test and has been issued a certificate of driver''s road test in accordance with § 391.31, or has presented an operator''s license or a certificate of road test which the motor carrier that employs him/her has accepted as equivalent to a road test in accordance with § 391.33.', 'A person may not drive a commercial motor vehicle unless qualified: for example at least 21 years old (with exceptions), able to read and speak English sufficiently, physically qualified, licensed, and having passed a road test or equivalent.', null, null, null, null, array['asphalt-paving', 'concrete', 'demolition', 'excavation', 'general-contracting', 'landscaping', 'tree-removal']::text[], array['dot', 'cdl', 'driver qualification', 'commercial driver']::text[], null, 'https://www.ecfr.gov/current/title-49/section-391.11', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '4d1590452b76f6727ded9110b5a4a4aa18025957e549948e10aa3b6e2919039e', 50),
  (md5('academykb:section:cfr:396.17(a)')::uuid, md5('academykb:source:fmcsa')::uuid, '396.17(a)', '49 CFR 396.17(a)', 'Periodic inspection: Every commercial motor vehicle must be inspected as required by this section', '49 CFR Part 396 › § 396.17 Periodic inspection', 'requirement', 'full_text', '(a) Every commercial motor vehicle must be inspected as required by this section. The inspection must include, at a minimum, the parts and accessories set forth in appendix A to this part. The term commercial motor vehicle includes each vehicle in a combination vehicle. For example, for a tractor semitrailer, full trailer combination, the tractor, semitrailer, and the full trailer (including the converter dolly if so equipped) must each be inspected.', 'Every commercial motor vehicle (each unit of a combination) must be inspected under this section, covering at least the items in Appendix A to Part 396.', null, null, null, null, array['asphalt-paving', 'concrete', 'demolition', 'excavation', 'general-contracting', 'landscaping', 'tree-removal']::text[], array['dot', 'vehicle inspection', 'annual inspection', 'commercial vehicle']::text[], null, 'https://www.ecfr.gov/current/title-49/section-396.17#p-396.17(a)', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '2b72aec5b0d1ad5fa44c0c5df74fdf48b682cc43bc30391a6137c4989bec5766', 51),
  (md5('academykb:section:cfr:382.103')::uuid, md5('academykb:source:fmcsa')::uuid, '382.103', '49 CFR 382.103', 'Applicability', '49 CFR Part 382 › § 382.103 Applicability', 'requirement', 'full_text', '(a) This part applies to service agents and to every person and to all employers of such persons who operate a commercial motor vehicle in commerce in any State and are subject to:
(1) The commercial driver''s license requirements of part 383 of this subchapter;
(2) The Licencia Federal de Conductor (Mexico) requirements; or
(3) The commercial drivers license requirements of the Canadian National Safety Code.
(b) An employer who employs himself/herself as a driver must comply with both the requirements in this part that apply to employers and the requirements in this part that apply to drivers. An employer who employs only himself/herself as a driver shall implement a random alcohol and controlled substances testing program of two or more covered employees in the random testing selection pool.
(c) The exceptions contained in § 390.3T(f) of this subchapter do not apply to this part. The employers and drivers identified in § 390.3T(f) of this subchapter must comply with the requirements of this part, unless otherwise specifically provided in paragraph (d) of this section.
(d) Exceptions. This part shall not apply to employers and their drivers:
(1) Required to comply only with the alcohol and/or controlled substances testing requirements of part 655 of this title (Federal Transit Administration alcohol and controlled substances testing regulations); or
(2) Who a State must waive from the requirements of part 383 of this subchapter. These individuals include active duty military personnel; members of the reserves; and members of the national guard on active duty, including personnel on full-time national guard duty, personnel on part-time national guard training and national guard military technicians (civilians who are required to wear military uniforms), and active duty U.S. Coast Guard personnel; or
(3) Who a State has, at its discretion, exempted from the requirements of part 383 of this subchapter. These individuals may be:
(i) Operators of a farm vehicle which is:
(A) Controlled and operated by a farmer;
(B) Used to transport either agricultural products, farm machinery, farm supplies, or both to or from a farm;
(C) Not used in the operations of a for-hire motor carrier, except for an exempt motor carrier as defined in § 390.5T of this subchapter; and
(D) Used within 241 kilometers (150 miles) of the farmer''s farm.
(ii) Firefighters or other persons who operate commercial motor vehicles which are necessary for the preservation of life or property or the execution of emergency governmental functions, are equipped with audible and visual signals, and are not subject to normal traffic regulation.
(4) Who operate “covered farm vehicles,” as defined in 49 CFR 390.5.', 'Drug and alcohol testing rules apply to employers and drivers who operate a commercial motor vehicle in commerce and are subject to the CDL requirements of Part 383. A self-employed driver must meet both the employer and the driver requirements.', null, null, null, null, array['asphalt-paving', 'concrete', 'demolition', 'excavation', 'general-contracting', 'landscaping', 'tree-removal']::text[], array['dot', 'drug testing', 'alcohol testing', 'cdl']::text[], null, 'https://www.ecfr.gov/current/title-49/section-382.103', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '9d2b0ab33da08fa02709433e2be74c7b678cd7c5ce0acc0a3171a7025ae4821d', 52),
  (md5('academykb:section:cfr:1952.1')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.1', '29 CFR 1952.1', 'Approved State Plan: South Carolina', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The South Carolina State plan received initial approval on December 6, 1972.
(b) The South Carolina State plan received final approval on December 18, 1987.
(c) Under the terms of the 1978 Court Order in AFL-CIO v. Marshall, compliance officer staffing levels (benchmarks) necessary for a “fully effective” enforcement program were required to be established for each State operating an approved State plan. In September 1984, South Carolina, in conjunction with OSHA, completed a reassessment of the staffing levels initially established in 1980 and proposed revised compliance staffing benchmar', 'South Carolina runs an OSHA-approved State Plan for private-sector employers. Its own safety standards and enforcement apply there.', null, null, null, null, '{}'::text[], array['osha state plan', 'state plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1952.1', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'ae35a1f3072b8ca57a7e197b5e633c7ea00693f6f2c3e2c0b46e332177c649d3', 53),
  (md5('academykb:section:cfr:1952.2')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.2', '29 CFR 1952.2', 'Approved State Plan: Oregon', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The Oregon State plan received initial approval on December 28, 1972.
(b) The Oregon State plan received final approval on May 12, 2005.
(c) Under the terms of the 1978 Court Order in AFL-CIO v. Marshall, compliance staffing levels (“benchmarks”) necessary for a “fully effective” enforcement program were required for each State operating an approved State plan. In October 1992, Oregon completed, in conjunction with OSHA, a reassessment of the health staffing level initially established in 1980 and proposed a revised health benchmark of 28 health compliance officers. Oregon elected to retai', 'Oregon runs an OSHA-approved State Plan for private-sector employers. Its own safety standards and enforcement apply there.', null, null, null, null, '{}'::text[], array['osha state plan', 'state plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1952.2', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '65c124b8150633348c2a06d4bb796b71d023156f8aa03dff3f25fc354e8f50bb', 54),
  (md5('academykb:section:cfr:1952.3')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.3', '29 CFR 1952.3', 'Approved State Plan: Utah', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The Utah State plan received initial approval on January 10, 1973.
(b) The Utah State plan received final approval on July 16, 1985.
(c) Under the terms of the 1978 Court Order in AFL-CIO v. Marshall, compliance staffing levels (benchmarks) necessary for a “fully effective” enforcement program were required to be established for each State operating an approved State plan. In September 1984, Utah, in conjunction with OSHA, completed a reassessment of the levels initially established in 1980 and proposed revised compliance staffing benchmarks of 10 safety and 9 health compliance officers. A', 'Utah runs an OSHA-approved State Plan for private-sector employers. Its own safety standards and enforcement apply there.', null, null, null, null, '{}'::text[], array['osha state plan', 'state plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1952.3', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '8e7f24d2bc0d31e0ef5cfe780bd89c14ae4f933a704244c8d98e81a23803135f', 55),
  (md5('academykb:section:cfr:1952.4')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.4', '29 CFR 1952.4', 'Approved State Plan: Washington', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The Washington State plan received initial approval on January 26, 1973.
(b) OSHA entered into an operational status agreement with Washington.
(c) The plan covers all private-sector employers and employees, with several notable exceptions, as well as State and local government employers and employees, within the State. For current information on these exceptions and for additional details about the plan, please visit http://www.osha.gov/dcsp/osp/stateprogs/washington.html.', 'Washington runs an OSHA-approved State Plan for private-sector employers. Its own safety standards and enforcement apply there.', null, null, null, null, '{}'::text[], array['osha state plan', 'state plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1952.4', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'f3655a103d41dad2c0684739ae7a4e79259e921096f8f8263a3738e9f1de497e', 56),
  (md5('academykb:section:cfr:1952.5')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.5', '29 CFR 1952.5', 'Approved State Plan: North Carolina', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The North Carolina State plan received initial approval on February 1, 1973.
(b) The North Carolina State plan received final approval on December 18, 1996.
(c) Under the terms of the 1978 Court Order in AFL-CIO v. Marshall, compliance staffing levels (“benchmarks”) necessary for a “fully effective” enforcement program were required for each State operating an approved State plan. In September 1984, North Carolina, in conjunction with OSHA, completed a reassessment of the levels initially established in 1980 and proposed revised benchmarks of 50 safety and 27 health compliance officers. Af', 'North Carolina runs an OSHA-approved State Plan for private-sector employers. Its own safety standards and enforcement apply there.', null, null, null, null, '{}'::text[], array['osha state plan', 'state plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1952.5', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '3abf109707760ba67bf443ba35df7f50e8219df95c1899877998f11c85fdb502', 57),
  (md5('academykb:section:cfr:1952.6')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.6', '29 CFR 1952.6', 'Approved State Plan: Iowa', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The Iowa State plan received initial approval on July 20, 1973.
(b) The Iowa State plan received final approval on July 2, 1985.
(c) Under the terms of the 1978 Court Order in AFL-CIO v. Marshall, compliance staffing levels (benchmarks) necessary for a “fully effective” enforcement program were required to be established for each State operating an approved State plan. In September 1984, Iowa, in conjunction with OSHA, completed a reassessment of the levels initially established in 1980 and proposed revised compliance staffing benchmarks of 16 safety and 13 health compliance officers. Afte', 'Iowa runs an OSHA-approved State Plan for private-sector employers. Its own safety standards and enforcement apply there.', null, null, null, null, '{}'::text[], array['osha state plan', 'state plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1952.6', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '4cd15f4aa126d3aafbcc9fd0e420a63719f326ad9d632a746dfe2fc2a0182f4e', 58),
  (md5('academykb:section:cfr:1952.7')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.7', '29 CFR 1952.7', 'Approved State Plan: California', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The California State plan received initial approval on May 1, 1973.
(b) OSHA entered into an operational status agreement with California.
(c) The plan covers all private-sector employers and employees, with several notable exceptions, as well as State and local government employers and employees, within the State. For current information on these exceptions and for additional details about the plan, please visit http://www.osha.gov/dcsp/osp/stateprogs/california.html.', 'California runs an OSHA-approved State Plan for private-sector employers. Its own safety standards and enforcement apply there.', null, null, null, null, '{}'::text[], array['osha state plan', 'state plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1952.7', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'c357e031d11992fa1fc56fc05749926619cc1c4cdcac230ce6f2ec3806ebbf3a', 59),
  (md5('academykb:section:cfr:1952.8')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.8', '29 CFR 1952.8', 'Approved State Plan: Minnesota', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The Minnesota State plan received initial approval on June 8, 1973.
(b) The Minnesota State plan received final approval on July 30, 1985.
(c) Under the terms of the 1978 Court Order in AFL-CIO v. Marshall, compliance staffing levels (benchmarks) necessary for a “fully effective” enforcement program were required to be established for each State operating an approved State plan. In September 1984 Minnesota, in conjunction with OSHA, completed a reassessment of the levels initially established in 1980 and proposed revised compliance staffing benchmarks of 31 safety and 12 health compliance ', 'Minnesota runs an OSHA-approved State Plan for private-sector employers. Its own safety standards and enforcement apply there.', null, null, null, null, '{}'::text[], array['osha state plan', 'state plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1952.8', 'verified', '2026-11-22T01:17:09Z'::timestamptz, 'e5fc441bda526fa1526b609d1e5ca6899119348233f020ad7f2b2c028045910d', 60),
  (md5('academykb:section:cfr:1952.9')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.9', '29 CFR 1952.9', 'Approved State Plan: Maryland', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The Maryland State plan received initial approval on July 5, 1973.
(b) The Maryland State plan received final approval on July 18, 1985.
(c) Under the terms of the 1978 Court Order in AFL-CIO v. Marshall, compliance staffing levels (benchmarks) necessary for a “fully effective” enforcement program were required to be established for each State operating an approved State plan. In September 1984 Maryland, in conjunction with OSHA, completed a reassessment of the levels initially established in 1980 and proposed revised compliance staffing benchmarks of 36 safety and 18 health compliance off', 'Maryland runs an OSHA-approved State Plan for private-sector employers. Its own safety standards and enforcement apply there.', null, null, null, null, '{}'::text[], array['osha state plan', 'state plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1952.9', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '02bea96377d7c91ea872d7a1ef407a5231f9b8f21f44beeb3863d56f0325e79f', 61),
  (md5('academykb:section:cfr:1952.10')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.10', '29 CFR 1952.10', 'Approved State Plan: Tennessee', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The Tennessee State plan received initial approval on July 5, 1973.
(b) The Tennessee State plan received final approval on July 22, 1985.
(c) Under the terms of the 1978 Court Order in AFL-CIO v. Marshall, compliance staffing levels (benchmarks) necessary for a “fully effective” enforcement program were required to be established for each State operating an approved State plan. In September 1984 Tennessee, in conjunction with OSHA, completed a reassessment of the levels initially established in 1980 and proposed revised compliance staffing benchmarks of 22 safety and 14 health compliance ', 'Tennessee runs an OSHA-approved State Plan for private-sector employers. Its own safety standards and enforcement apply there.', null, null, null, null, '{}'::text[], array['osha state plan', 'state plan']::text[], null, 'https://www.ecfr.gov/current/title-29/section-1952.10', 'verified', '2026-11-22T01:17:09Z'::timestamptz, '2235e6d57d4326df136e7159d6b1e82c8598918af43d86905eb13f7bf51b7bd2', 62),
  (md5('academykb:section:cfr:1952.11')::uuid, md5('academykb:source:osha-1952')::uuid, '1952.11', '29 CFR 1952.11', 'Approved State Plan: Kentucky', '29 CFR Part 1952 › Subpart A', 'scope', 'full_text', '(a) The Kentucky State plan received initial approval on July 31, 1973.
