insert into public.academy_kb_verifications (target_type, target_id, checked_at, method, result, source_url, content_hash, evidence, notes)
select v.* from (values
  ('source', (md5('academykb:source:osha-1926')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.ecfr.gov/current/title-29/section-1926.20', '5f391c8ce4fa0ba4df607005724e7676b97c614dc7a29e7441d090150e48abbb', '§ 1926.20 General safety and health provisions. (a) Contractor requirements. (1) Section 107 of the Act requires that it shall be a condition of each contract which is entered into under legislation subject to Reorganization Plan Number 14 of 1950 (64 Stat. 1267), as defined in § 1926.12, and is for construction, alteration, and/or repair, including painting and decorating, that no contractor or subcontractor for any part of the contract work shall require any laborer or mechanic employed in the performance of the contract to work in surround', null),
  ('source', (md5('academykb:source:osha-1904')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.ecfr.gov/current/title-29/section-1904.1', 'bcc916339fd7df99983f6df847697a5c9d152a7eee6d70d61c3d69858bf0cb6c', '§ 1904.1 Partial exemption for employers with 10 or fewer employees. (a) Basic requirement. (1) If your company had 10 or fewer employees at all times during the last calendar year, you do not need to keep OSHA injury and illness records unless OSHA or the Bureau of Labor Statistics informs you in writing that you must keep records under § 1904.41 or § 1904.42. However, as required by § 1904.39, all employers covered by the OSH Act must report to OSHA any work-related incident that results in a fatality, the in-patient hospitalization of one or more employees, an', null),
  ('source', (md5('academykb:source:osha-1952')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.ecfr.gov/current/title-29/section-1952.1', 'ae35a1f3072b8ca57a7e197b5e633c7ea00693f6f2c3e2c0b46e332177c649d3', '§ 1952.1 South Carolina. (a) The South Carolina State plan received initial approval on December 6, 1972.
(b) The South Carolina State plan received final approval on December 18, 1987.
(c) Under the terms of the 1978 Court Order in AFL-CIO v. Marshall, compliance officer staffing levels (benchmarks) necessary for a “fully effective” enforcement program were required to be established for each State operating an approved ', null),
  ('source', (md5('academykb:source:epa-745')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.ecfr.gov/current/title-40/section-745.82', '84b5cc33b9d91b58e24947c90202c3a26f192e946fab93c5175726c2a09f4363', '§ 745.82 Applicability. (a) This subpart applies to all renovations performed for compensation in target housing and child-occupied facilities, except for the following:
(1) Renovations in target housing or child-occupied facilities in which a written determination has been made by an inspector or risk assessor (certified pursuant to either Federal regulations at § 745.226 or a State or Tribal certification program authorized pursuant to § 745.324) that the components affected by the renovation are free of paint or oth', null),
  ('source', (md5('academykb:source:fmcsa')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.ecfr.gov/current/title-49/section-391.11', '4d1590452b76f6727ded9110b5a4a4aa18025957e549948e10aa3b6e2919039e', '§ 391.11 General qualifications of drivers. (a) A person shall not drive a commercial motor vehicle unless he/she is qualified to drive a commercial motor vehicle. Except as provided in § 391.63, a motor carrier shall not require or permit a person to drive a commercial motor vehicle unless that person is qualified to drive a commercial motor vehicle.
(b) Except as provided in subpart G of this part, a person is qualified to drive a motor vehicle if he/she—
(1) Is at least 21 years old;
(2) Can read and speak the English language sufficie', null),
  ('source', (md5('academykb:source:mn-1300')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1300.0120/', '78f5d1f923855477b9d5556dae706894cae1ce1c32c414c2dbcf31bb3133dccc', 'Subpart 1. Required. An owner or authorized agent who intends to construct, enlarge, alter, repair, move, demolish, or change the occupancy of a building or structure, or to erect, install, enlarge, alter, repair, remove, convert, or replace any gas, mechanical, electrical, plumbing system, or other equipment, the installation of which is regulated by the code; or cause any such work to be done, shall first make application to the building official and obtain the required permit.', null),
  ('source', (md5('academykb:source:mn-1305')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1305.0011/', '739a1090d2a6e76d93f5aa0d1f45a5ebc3bd5798a45875e1f97ad159281cb440', 'Subpart 1. General. For purposes of this chapter, "IBC" means the 2018 edition of the International Building Code as promulgated by the International Code Council, Inc. (ICC), Washington, D.C. The IBC is incorporated by reference and made part of the Minnesota State Building Code except as qualified by the applicable provisions in Minnesota Rules, chapter 1300, and as amended in this chapter. Portions of this chapter reproduce excerpts from the 2018 IBC, International Code Council, Inc., Washington, D.C., copyright 2017, reproduced with permission, all rights reserved. The IBC is not subject to frequent change and a copy of the IBC, with amendments for use in Minnesota, is available in the office of the commissioner of labor and industry.', null),
  ('source', (md5('academykb:source:mn-1309')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1309.0010/', 'c74b085e5f84045f9c4da984ee00459581f53ade9e63880f41625734b1d3f5cf', 'Subpart 1. Generally. The 2018 edition of the International Residential Code ("IRC") as promulgated by the International Code Council, Inc. ("ICC"), Washington, D.C., is incorporated by reference and made part of the Minnesota State Building Code except as qualified by the applicable provisions in Minnesota Rules, chapter 1300, and as amended in this chapter. Portions of this publication reproduce excerpts from the 2018 IRC, International Code Council, Inc., Washington, D.C., copyright 2017, reproduced with permission, all rights reserved. The IRC is not subject to frequent change and a copy of the IRC, with amendments for use in Minnesota, is available in the office of the commissioner of labor and industry.', null),
  ('source', (md5('academykb:source:mn-1315')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1315.0200/', 'e7bff6a1149935ba622b7735d09b2e7c0843bacc41b8195b216746e237b1ccab', 'Subpart 1. Title. This chapter shall be known and cited as the "Minnesota Electrical Code."', null),
  ('source', (md5('academykb:source:mn-1322')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1322.0010/', '9c93fe7e15b79b2ccb0ddd6e40f19af0dee12fb59ebfc54c5a36fb7e9f0c62f2', 'Subpart 1. General. Chapters 2(RE) to 5(RE) of the Residential Provisions of the 2012 edition of the International Energy Conservation Code (IECC) as promulgated by the International Code Council, Inc. (ICC), Washington, DC, is incorporated by reference and made part of the Minnesota State Building Code except as qualified by the applicable provisions in Minnesota Rules, chapter 1300, and as amended in this chapter. Portions of this publication reproduce excerpts from the 2012 IECC, International Code Council, Inc. Washington, DC, copyright 2012, reproduced with permission, all rights reserved. The 2012 IECC is not subject to frequent change and a copy of the 2012 IECC with amendments for use in Minnesota is available in the office of the commissioner of labor and industry.', null),
  ('source', (md5('academykb:source:mn-1346')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1346.0050/', '88fcf304caa20f66aff8f3f18313596b9acde1f5f18e27eb4e216bc552bca03a', 'Parts 1346.0050 to 1346.1606 are known and may be cited as the "Minnesota Mechanical Code." Chapters 2 to 15 of the 2018 edition of the International Mechanical Code ("IMC"), promulgated by the International Code Council, Inc., Washington, DC, are incorporated by reference as part of the Minnesota Mechanical Code except as qualified by the applicable provisions in Minnesota Rules, chapter 1300, and as amended in this chapter. Portions of this chapter reproduce excerpts from the 2018 IMC, International Code Council, Inc., Washington, DC, copyright 2017, reproduced with permission, all rights reserved. The IMC is not subject to frequent change and a copy of the IMC with amendments for use in Minnesota is available in the office of the commissioner of labor and industry. Chapters 1 to 10 and 12 to 15 of the 2017 edition of NFPA 96 Standard for Ventilation Control and Fire Protection of Commercial Cooking Operations, promulgated by the National Fire Protection Association, 1 Batterymarch Park, Quincy, MA 02169-7471, are incorporated by reference as part of the Minnesota Mechanical Code as amended in this chapter. As used in this code, "NFPA 96" means the NFPA 96 Standard for Ventilation Control and Fire Protection of Commercial Cooking Operations chapters that are incorporated into this code. Portions of this chapter reproduce text and tables from the NFPA 96. The NFPA 96 is copyrighted, 2017, by the National Fire Protection Association. All rights reserved. The NFPA 96 is not subject to frequent change and a copy of the NFPA 96, with amendments for use in Minnesota, is available in the office of the commissioner of labor and industry. The 2016 edition of ANSI/ASHRAE 62.2 Ventilation and Acceptable Indoor Air Quality in Residential Buildings, promulgated by the American Society of Heating, Refrigerating and Air-Conditioning Engineers, 1791 Tullie Circle NE, Atlanta, GA 30329, and the American National Standards Institute is incorporated by reference as part of the Minnesota Mechanical Code. The ASHRAE 62.2 is not subject to frequent change, and a copy of the ASHRAE 62.2 is available in the office of the commissioner of labor and industry. Chapters 1 to 9 of the 2016 edition of ANSI/ASHRAE 154 Ventilation for Commercial Cooking Operations, promulgated by the American Society of Heating, Refrigerating and Air-Conditioning Engineers, 1791 Tullie Circle NE, Atlanta, GA 30329, and the American National Standards Institute is incorporated by reference as part of the Minnesota Mechanical Code, as amended in this chapter. As used in this code, "ASHRAE 154" means the ANSI/ASHRAE 154 Ventilation for Commercial Cooking Operations chapters that are incorporated into this code. The ASHRAE 154 is not subject to frequent change, and a copy of the ASHRAE 154 is available in the office of the commissioner of labor and industry.', null),
  ('source', (md5('academykb:source:irc-2018')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1309.0010/', 'c74b085e5f84045f9c4da984ee00459581f53ade9e63880f41625734b1d3f5cf', 'Subpart 1. Generally. The 2018 edition of the International Residential Code ("IRC") as promulgated by the International Code Council, Inc. ("ICC"), Washington, D.C., is incorporated by reference and made part of the Minnesota State Building Code except as qualified by the applicable provisions in Minnesota Rules, chapter 1300, and as amended in this chapter. Portions of this publication reproduce excerpts from the 2018 IRC, International Code Council, Inc., Washington, D.C., copyright 2017, reproduced with permission, all rights reserved. The IRC is not subject to frequent change and a copy of the IRC, with amendments for use in Minnesota, is available in the office of the commissioner of labor and industry.', 'Edition confirmed by the adopting jurisdiction''s official text.'),
  ('source', (md5('academykb:source:ibc-2018')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1305.0011/', '739a1090d2a6e76d93f5aa0d1f45a5ebc3bd5798a45875e1f97ad159281cb440', 'Subpart 1. General. For purposes of this chapter, "IBC" means the 2018 edition of the International Building Code as promulgated by the International Code Council, Inc. (ICC), Washington, D.C. The IBC is incorporated by reference and made part of the Minnesota State Building Code except as qualified by the applicable provisions in Minnesota Rules, chapter 1300, and as amended in this chapter. Portions of this chapter reproduce excerpts from the 2018 IBC, International Code Council, Inc., Washington, D.C., copyright 2017, reproduced with permission, all rights reserved. The IBC is not subject to frequent change and a copy of the IBC, with amendments for use in Minnesota, is available in the office of the commissioner of labor and industry.', 'Edition confirmed by the adopting jurisdiction''s official text.'),
  ('source', (md5('academykb:source:imc-2018')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1346.0050/', '88fcf304caa20f66aff8f3f18313596b9acde1f5f18e27eb4e216bc552bca03a', 'Parts 1346.0050 to 1346.1606 are known and may be cited as the "Minnesota Mechanical Code." Chapters 2 to 15 of the 2018 edition of the International Mechanical Code ("IMC"), promulgated by the International Code Council, Inc., Washington, DC, are incorporated by reference as part of the Minnesota Mechanical Code except as qualified by the applicable provisions in Minnesota Rules, chapter 1300, and as amended in this chapter. Portions of this chapter reproduce excerpts from the 2018 IMC, International Code Council, Inc., Washington, DC, copyright 2017, reproduced with permission, all rights reserved. The IMC is not subject to frequent change and a copy of the IMC with amendments for use in Minnesota is available in the office of the commissioner of labor and industry. Chapters 1 to 10 and 12 to 15 of the 2017 edition of NFPA 96 Standard for Ventilation Control and Fire Protection of Commercial Cooking Operations, promulgated by the National Fire Protection Association, 1 Batterymarch Park, Quincy, MA 02169-7471, are incorporated by reference as part of the Minnesota Mechanical Code as amended in this chapter. As used in this code, "NFPA 96" means the NFPA 96 Standard for Ventilation Control and Fire Protection of Commercial Cooking Operations chapters that are incorporated into this code. Portions of this chapter reproduce text and tables from the NFPA 96. The NFPA 96 is copyrighted, 2017, by the National Fire Protection Association. All rights reserved. The NFPA 96 is not subject to frequent change and a copy of the NFPA 96, with amendments for use in Minnesota, is available in the office of the commissioner of labor and industry. The 2016 edition of ANSI/ASHRAE 62.2 Ventilation and Acceptable Indoor Air Quality in Residential Buildings, promulgated by the American Society of Heating, Refrigerating and Air-Conditioning Engineers, 1791 Tullie Circle NE, Atlanta, GA 30329, and the American National Standards Institute is incorporated by reference as part of the Minnesota Mechanical Code. The ASHRAE 62.2 is not subject to frequent change, and a copy of the ASHRAE 62.2 is available in the office of the commissioner of labor and industry. Chapters 1 to 9 of the 2016 edition of ANSI/ASHRAE 154 Ventilation for Commercial Cooking Operations, promulgated by the American Society of Heating, Refrigerating and Air-Conditioning Engineers, 1791 Tullie Circle NE, Atlanta, GA 30329, and the American National Standards Institute is incorporated by reference as part of the Minnesota Mechanical Code, as amended in this chapter. As used in this code, "ASHRAE 154" means the ANSI/ASHRAE 154 Ventilation for Commercial Cooking Operations chapters that are incorporated into this code. The ASHRAE 154 is not subject to frequent change, and a copy of the ASHRAE 154 is available in the office of the commissioner of labor and industry.', 'Edition confirmed by the adopting jurisdiction''s official text.'),
  ('source', (md5('academykb:source:iecc-2012')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1322.0010/', '9c93fe7e15b79b2ccb0ddd6e40f19af0dee12fb59ebfc54c5a36fb7e9f0c62f2', 'Subpart 1. General. Chapters 2(RE) to 5(RE) of the Residential Provisions of the 2012 edition of the International Energy Conservation Code (IECC) as promulgated by the International Code Council, Inc. (ICC), Washington, DC, is incorporated by reference and made part of the Minnesota State Building Code except as qualified by the applicable provisions in Minnesota Rules, chapter 1300, and as amended in this chapter. Portions of this publication reproduce excerpts from the 2012 IECC, International Code Council, Inc. Washington, DC, copyright 2012, reproduced with permission, all rights reserved. The 2012 IECC is not subject to frequent change and a copy of the 2012 IECC with amendments for use in Minnesota is available in the office of the commissioner of labor and industry.', 'Edition confirmed by the adopting jurisdiction''s official text.'),
  ('source', (md5('academykb:source:nec-2026')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.revisor.mn.gov/rules/1315.0200/', 'e7bff6a1149935ba622b7735d09b2e7c0843bacc41b8195b216746e237b1ccab', 'Subpart 1. Title. This chapter shall be known and cited as the "Minnesota Electrical Code."', 'Edition confirmed by the adopting jurisdiction''s official text.'),
  ('source', (md5('academykb:source:nec-2023')::uuid)::text, '2026-11-22T01:17:09Z'::timestamptz, 'official_text', 'verified', 'https://www.dli.mn.gov/business/electrical-contractors', null, '"adopted the 2026 National Electrical Code (NEC) with an effective date of Aug. 17, 2026" … "Electrical permits filed before Aug. 17, 2026, must comply with the 2023 NEC"', 'Edition confirmed by the adopting jurisdiction''s official text.'),
